insert into public.questoes (id_planilha, tipo, simulado_numero, numero_na_prova, area, subtema, dificuldade, ano_origem, fonte, enunciado, alternativa_a, alternativa_b, alternativa_c, alternativa_d, resposta_correta, comentario_correta, comentario_erros, status)
values
  ('SIM1-001', 'simulado', '1', '1', 'Clínica Médica', 'Síndrome coronariana aguda', 'Médio', null, null, 'Paciente de 58 anos, hipertenso, chega à UPA com dor torácica opressiva iniciada há 40 minutos, irradiando para o braço esquerdo, associada a sudorese. ECG mostra supradesnivelamento de ST em parede anterior. Qual a conduta inicial mais adequada?', 'Encaminhar para angioplastia primária ou trombólise, conforme tempo porta-balão', 'Solicitar teste ergométrico de urgência', 'Prescrever apenas analgesia e observação por 6 horas', 'Solicitar troponina e aguardar resultado antes de decidir', 'A', 'IAMCSST é diagnóstico clínico-eletrocardiográfico; não se aguarda troponina para decidir reperfusão. A prioridade é restaurar o fluxo coronariano o mais rápido possível (angioplastia primária <90min ou trombólise se indisponível).', 'B: contraindicado na fase aguda de um IAM. C: subtrata quadro com risco de morte. D: atrasa a reperfusão sem necessidade.', 'Em revisão'),
  ('SIM1-002', 'simulado', '1', '2', 'Clínica Médica', 'Pneumonia adquirida na comunidade', 'Médio', null, null, 'Paciente de 45 anos, previamente hígido, procura a UBS com tosse produtiva, febre de 38,5°C e dispneia leve há 3 dias. Ao exame: FR 24irpm, PA 118x76mmHg, FC 92bpm, saturação 95% em ar ambiente, orientado, estertores em base pulmonar direita. Radiografia de tórax mostra consolidação lobar. Escore CURB-65 = 0. Qual a conduta mais adequada?', 'Internação hospitalar para antibioticoterapia intravenosa imediata', 'Tratamento ambulatorial com amoxicilina e reavaliação clínica em 48-72 horas', 'Solicitar tomografia de tórax antes de decidir a conduta', 'Encaminhar diretamente para UTI por insuficiência respiratória', 'B', 'CURB-65 = 0 indica baixo risco de mortalidade, permitindo tratamento ambulatorial. Amoxicilina é a primeira escolha para PAC leve em paciente sem comorbidades, com reavaliação em 48-72h para checar resposta clínica.', 'A: internação é desnecessária em baixo risco, aumentando custo e exposição a infecção hospitalar sem benefício. C: TC não é rotina quando a radiografia já confirma o diagnóstico. D: não há critérios de gravidade (saturação preservada, sem hipotensão/confusão) que justifiquem UTI.', 'Em revisão'),
  ('SIM1-003', 'simulado', '1', '3', 'Clínica Médica', 'Urgência x emergência hipertensiva', 'Médio', null, null, 'Paciente de 62 anos, hipertenso em uso irregular de medicação, comparece à UBS com cefaleia occipital há 2 dias, sem outros sintomas. PA 200x110mmHg em duas aferições, exame neurológico normal, fundoscopia sem alterações agudas, sem sinais de lesão aguda de órgão-alvo. Qual a conduta mais adequada?', 'Encaminhar para internação em UTI para monitorização contínua', 'Solicitar tomografia de crânio de urgência antes de qualquer conduta', 'Ajustar/reiniciar medicação oral, reduzindo a PA gradualmente em 24-48h, com retorno agendado', 'Reduzir a PA para valores normais em minutos com anti-hipertensivo endovenoso', 'C', 'Trata-se de urgência hipertensiva (PA muito elevada sem lesão aguda de órgão-alvo): o manejo padrão é redução gradual da PA em 24-48h com medicação oral, evitando quedas abruptas que podem causar hipoperfusão de órgãos.', 'A: não há indicação de UTI sem sinais de emergência. B: sem sinais neurológicos focais, TC não é obrigatória com urgência. D: redução rápida por via IV é reservada para emergência hipertensiva (com lesão de órgão-alvo), podendo causar isquemia se usada aqui.', 'Em revisão'),
  ('SIM1-004', 'simulado', '1', '4', 'Clínica Médica', 'Insuficiência cardíaca descompensada', 'Médio', null, null, 'Paciente de 68 anos, com histórico de ICFEr (FEVE 30%), procura o PS com piora da dispneia aos mínimos esforços, ortopneia e edema de membros inferiores há 5 dias. Ao exame: estertores crepitantes bibasais, turgência jugular a 45°, PA 130x85mmHg, FC 98bpm, saturação 91% em ar ambiente. Qual a conduta inicial mais adequada?', 'Diurético de alça endovenoso associado a oxigenoterapia e monitorização', 'Alta com ajuste de medicação oral e retorno ambulatorial em 7 dias', 'Betabloqueador em dose plena imediatamente para reduzir a frequência cardíaca', 'Reposição volêmica agressiva para melhorar o débito cardíaco', 'A', 'Paciente com sinais de congestão (estertores, turgência jugular, edema) necessita de diurético IV para depleção de volume e oxigenoterapia para hipoxemia; a monitorização é essencial nesse cenário de descompensação aguda.', 'B: sinais de gravidade (saturação 91%, congestão importante) contraindicam alta sem tratamento hospitalar. C: iniciar/aumentar betabloqueador na fase aguda descompensada pode piorar o quadro; é indicado após estabilização. D: paciente congesto não deve receber volume adicional.', 'Em revisão'),
  ('SIM1-005', 'simulado', '1', '5', 'Clínica Médica', 'DPOC - exacerbação aguda', 'Médio', null, null, 'Paciente de 65 anos, tabagista, com DPOC prévio, apresenta piora da dispneia, aumento do volume e purulência do escarro há 3 dias. Ao exame: uso de musculatura acessória, sibilos difusos, saturação 90% em ar ambiente. Qual a conduta mais adequada?', 'Broncodilatador de curta ação + corticoide sistêmico + antibiótico, com oxigenoterapia controlada', 'Apenas broncodilatador de longa ação, sem necessidade de outras medidas', 'Observação sem tratamento farmacológico, pois se trata de quadro autolimitado', 'Ventilação mecânica invasiva imediata, independentemente da resposta inicial', 'A', 'A exacerbação de DPOC com aumento do volume/purulência do escarro (critérios de Anthonisen) e sinais de gravidade indica broncodilatador de curta ação, corticoide sistêmico e antibiótico, associados a oxigenoterapia titulada para evitar hipercapnia.', 'B: broncodilatador de longa ação não é indicado na crise aguda. C: quadro com sinais de gravidade não deve ser apenas observado. D: ventilação invasiva é reservada para falha de tratamento clínico/ventilação não invasiva.', 'Em revisão'),
  ('SIM1-006', 'simulado', '1', '6', 'Clínica Médica', 'AVC isquêmico - janela terapêutica', 'Difícil', null, null, 'Paciente de 70 anos é trazido ao PS com hemiparesia direita e disartria de início há 2 horas. Glicemia capilar normal, PA 170x95mmHg, sem histórico de sangramento recente ou cirurgia. TC de crânio sem sinais de hemorragia. Qual a conduta mais adequada dentro da janela terapêutica?', 'Indicar craniotomia descompressiva de urgência', 'Aguardar 24 horas para repetir a TC antes de qualquer tratamento', 'Iniciar anticoagulação plena imediatamente, independentemente de outros exames', 'Avaliar critérios de elegibilidade e considerar trombólise endovenosa', 'D', 'Dentro da janela de até 4,5 horas do início dos sintomas, com TC excluindo hemorragia, deve-se avaliar critérios de elegibilidade (contraindicações, tempo, gravidade) para trombólise endovenosa, tratamento capaz de reduzir sequelas no AVC isquêmico.', 'A: craniotomia descompressiva é reservada para casos específicos (edema maligno), não é conduta inicial. B: atraso reduz a janela terapêutica e a eficácia do tratamento. C: anticoagulação plena não é a conduta inicial no AVC isquêmico agudo, podendo aumentar risco de transformação hemorrágica.', 'Em revisão'),
  ('SIM1-007', 'simulado', '1', '7', 'Clínica Médica', 'Hipotireoidismo - diagnóstico e tratamento', 'Fácil', null, null, 'Mulher de 45 anos relata fadiga, ganho de peso, pele seca e constipação há alguns meses. Exame físico com bradicardia leve e pele seca. TSH elevado, T4 livre baixo. Qual a conduta mais adequada?', 'Solicitar apenas ultrassonografia de tireoide, sem necessidade de tratamento medicamentoso', 'Iniciar propiltiouracila para controle dos sintomas', 'Aguardar repetição dos exames em 6 meses antes de iniciar qualquer tratamento', 'Iniciar levotiroxina em dose ajustada ao peso, com reavaliação de TSH em 6-8 semanas', 'D', 'TSH elevado com T4 livre baixo confirma hipotireoidismo primário; o tratamento é reposição com levotiroxina, com reavaliação laboratorial em 6-8 semanas para ajuste de dose.', 'A: USG não é necessária para diagnóstico/tratamento inicial de hipotireoidismo primário sem nódulos palpáveis. B: propiltiouracila é usada no hipertireoidismo, não no hipotireoidismo. C: atrasar o tratamento prolonga os sintomas e riscos metabólicos desnecessariamente.', 'Em revisão'),
  ('SIM1-008', 'simulado', '1', '8', 'Clínica Médica', 'Doença renal crônica - estadiamento', 'Médio', null, null, 'Paciente de 60 anos, diabético e hipertenso, apresenta taxa de filtração glomerular estimada de 40 mL/min/1,73m² em dois exames com intervalo de 3 meses, associada a albuminúria moderada. Qual a classificação e conduta mais adequada?', 'Insuficiência renal aguda; suspender toda a medicação em uso', 'DRC estágio 5; iniciar diálise imediatamente', 'Função renal normal para a idade; não é necessária nenhuma conduta específica', 'DRC estágio 3b; controle rigoroso de pressão arterial e glicemia, com encaminhamento ao nefrologista', 'D', 'TFG entre 30-44 mL/min/1,73m² por mais de 3 meses caracteriza DRC estágio 3b; a conduta envolve controle dos fatores de progressão (PA, glicemia) e encaminhamento para acompanhamento especializado.', 'A: trata-se de doença crônica (persistente por 3 meses), não aguda; suspender toda medicação sem avaliação é inadequado. B: estágio 5 corresponde a TFG <15; não é o caso aqui. C: TFG reduzida de forma persistente não é normal para a idade e requer conduta.', 'Em revisão'),
  ('SIM1-009', 'simulado', '1', '9', 'Clínica Médica', 'Tuberculose - tratamento', 'Fácil', null, null, 'Paciente de 35 anos, tosse produtiva há 4 semanas, febre vespertina, sudorese noturna e emagrecimento. Baciloscopia de escarro positiva para BAAR. Qual o esquema terapêutico inicial mais adequado, segundo o protocolo do Ministério da Saúde?', 'Amoxicilina com ácido clavulânico por 14 dias', 'Isoniazida isolada por 6 meses', 'Esquema básico com rifampicina, isoniazida, pirazinamida e etambutol por 2 meses, seguido de rifampicina e isoniazida por 4 meses', 'Apenas repouso e acompanhamento clínico, sem necessidade de antibioticoterapia', 'C', 'O esquema básico para tuberculose no Brasil é RIPE (rifampicina, isoniazida, pirazinamida, etambutol) por 2 meses na fase intensiva, seguido de rifampicina e isoniazida por mais 4 meses na fase de manutenção, totalizando 6 meses.', 'A: antibiótico de amplo espectro comum não trata tuberculose, que requer esquema específico. B: isoniazida isolada é usada para tratamento de infecção latente, não de tuberculose ativa. D: tuberculose ativa exige tratamento antimicrobiano específico.', 'Em revisão'),
  ('SIM1-010', 'simulado', '1', '10', 'Clínica Médica', 'HIV - profilaxia pós-exposição', 'Médio', null, null, 'Profissional de saúde sofre acidente perfurocortante com agulha usada em paciente HIV positivo, há 1 hora. Qual a conduta mais adequada?', 'Aguardar resultado de sorologia do profissional antes de qualquer medida', 'Não há necessidade de profilaxia se o profissional usava luvas no momento do acidente', 'Iniciar profilaxia pós-exposição (PEP) o mais rápido possível, idealmente nas primeiras 2 horas, até no máximo 72 horas', 'Iniciar profilaxia apenas se houver sintomas de infecção aguda', 'C', 'A profilaxia pós-exposição ao HIV deve ser iniciada o quanto antes, idealmente nas primeiras 2 horas, com eficácia decrescente até o limite de 72 horas após a exposição, independentemente do uso de EPI no momento do acidente.', 'A: não se deve aguardar resultado sorológico para iniciar a profilaxia, dado o tempo crítico de eficácia. B: o uso de luvas não elimina o risco de exposição percutânea por perfurocortante. D: a profilaxia é preventiva, não depende de sintomas (que indicariam infecção já estabelecida).', 'Em revisão'),
  ('SIM1-011', 'simulado', '1', '11', 'Clínica Médica', 'Emergência hipertensiva / edema agudo de pulmão', 'Difícil', null, null, 'Paciente de 70 anos chega ao PS com dispneia intensa, ortopneia, PA 220x130mmHg, estertores crepitantes bilaterais até ápices, agitação. ECG sem alterações isquêmicas agudas. Qual a conduta mais adequada?', 'Reduzir a PA por via oral, gradualmente, ao longo de 24-48h', 'Reduzir a PA rapidamente com anti-hipertensivo IV (ex: nitroglicerina), associado a diurético e suporte ventilatório', 'Priorizar apenas sedação, sem tratar a pressão arterial', 'Aguardar sem intervenção até estabilização espontânea', 'B', 'Emergência hipertensiva com edema agudo de pulmão exige redução rápida (mas controlada) da PA por via IV, associada a diurético e suporte de oxigenação, para reverter a lesão aguda de órgão-alvo.', 'A: redução gradual é para urgência hipertensiva, não para emergência com lesão aguda de órgão-alvo. C: sedação isolada não trata a causa hemodinâmica do quadro. D: atraso pode ser fatal em EAP hipertensivo.', 'Em revisão'),
  ('SIM1-012', 'simulado', '1', '12', 'Clínica Médica', 'Síndrome nefrótica', 'Médio', null, null, 'Criança de 4 anos apresenta edema periorbital e de membros inferiores, proteinúria maciça, hipoalbuminemia e hiperlipidemia. Qual a hipótese diagnóstica mais provável e conduta inicial?', 'Infecção urinária; iniciar antibiótico empírico', 'Síndrome nefrótica; iniciar corticoterapia e investigar complicações (infecção, trombose)', 'Insuficiência renal aguda; iniciar diálise imediata', 'Síndrome nefrítica; iniciar anti-hipertensivo isolado', 'B', 'A tríade de edema, proteinúria maciça, hipoalbuminemia e hiperlipidemia caracteriza síndrome nefrótica; em crianças, a causa mais comum é a doença de lesões mínimas, respondendo bem a corticoterapia.', 'A: quadro não é compatível com infecção urinária isolada. C: não há indicação de diálise sem sinais de IRA/uremia grave. D: síndrome nefrítica cursa com hematúria e hipertensão, quadro diferente.', 'Em revisão'),
  ('SIM1-013', 'simulado', '1', '13', 'Clínica Médica', 'Anemia ferropriva', 'Fácil', null, null, 'Mulher de 35 anos com fadiga e palidez. Hemograma: hemoglobina 9,5 g/dL, VCM baixo, RDW elevado. Ferritina baixa. Relata menorragia há meses. Qual a conduta mais adequada?', 'Suplementação de vitamina B12 isolada', 'Observação sem tratamento, pois anemia leve não requer conduta', 'Transfusão sanguínea imediata, independente da estabilidade clínica', 'Suplementação de ferro oral, investigação e tratamento da causa do sangramento', 'D', 'Anemia microcítica com ferritina baixa confirma deficiência de ferro; a conduta é reposição oral de ferro associada à investigação e tratamento da causa (aqui, menorragia).', 'A: B12 trata anemia macrocítica, não microcítica ferropriva. B: hemoglobina 9,5 com sintomas exige tratamento. C: transfusão não é indicada rotineiramente em anemia estável sem repercussão hemodinâmica.', 'Em revisão'),
  ('SIM1-014', 'simulado', '1', '14', 'Clínica Médica', 'Doença péptica / H. pylori', 'Fácil', null, null, 'Paciente de 40 anos com dor epigástrica em queimação, que melhora com alimentação, há 2 meses. Endoscopia mostra úlcera duodenal. Teste da urease positivo. Qual a conduta mais adequada?', 'Cirurgia de urgência para tratamento definitivo da úlcera', 'Terapia de erradicação do H. pylori (IBP + dois antibióticos) por 14 dias', 'Apenas IBP isolado por 4 semanas, sem necessidade de erradicar H. pylori', 'Antiácidos isolados, sem necessidade de outros tratamentos', 'B', 'Úlcera duodenal associada a H. pylori positivo tem indicação de terapia de erradicação (esquema tríplice) por 14 dias, reduzindo recorrência e complicações.', 'A: cirurgia é reservada para complicações. C: sem erradicar o H. pylori, a recorrência é alta. D: antiácidos isolados não tratam a causa nem cicatrizam adequadamente a úlcera.', 'Em revisão'),
  ('SIM1-015', 'simulado', '1', '15', 'Clínica Médica', 'Cirrose hepática - ascite', 'Médio', null, null, 'Paciente de 55 anos, etilista crônico, com cirrose hepática conhecida, apresenta aumento do volume abdominal, macicez móvel à percussão. Paracentese diagnóstica mostra gradiente de albumina soro-ascite (GASA) ≥1,1. Qual a conduta inicial mais adequada?', 'Paracentese de grande volume diária, independentemente dos sintomas', 'Antibioticoterapia empírica para todos os casos de ascite, sem necessidade de investigação', 'Restrição de sódio na dieta e diurético (espironolactona ± furosemida)', 'Transplante hepático imediato como única opção terapêutica', 'C', 'Ascite por hipertensão portal (GASA ≥1,1) é tratada inicialmente com restrição de sódio e diuréticos, reservando paracentese terapêutica para ascite tensa/refratária.', 'A: paracentese diária não é rotina. B: antibiótico é indicado se houver suspeita de peritonite bacteriana espontânea, não em toda ascite. D: transplante é considerado em estágios avançados, não é conduta imediata.', 'Em revisão'),
  ('SIM1-016', 'simulado', '1', '16', 'Clínica Médica', 'Fibrilação atrial - anticoagulação', 'Médio', null, null, 'Paciente de 72 anos, hipertenso e diabético, apresenta fibrilação atrial persistente identificada em ECG de rotina, assintomática. Qual a conduta mais adequada em relação à prevenção de eventos tromboembólicos?', 'Não é necessária anticoagulação, pois o paciente está assintomático', 'Cardioversão elétrica imediata, sem avaliação de risco tromboembólico', 'Calcular o escore CHA2DS2-VASc e considerar anticoagulação oral conforme o risco', 'Indicar apenas AAS em dose antiagregante, sem necessidade de anticoagulante', 'C', 'Em FA, a decisão de anticoagular independe de sintomas e deve ser guiada pelo escore CHA2DS2-VASc; paciente hipertenso, diabético e idoso provavelmente tem escore elevado, indicando anticoagulação oral.', 'A: risco tromboembólico não depende de sintomas. B: cardioversão sem avaliação de risco/anticoagulação prévia pode aumentar risco de embolização. D: AAS isolado não é tão eficaz quanto anticoagulante oral em FA com risco elevado.', 'Em revisão'),
  ('SIM1-017', 'simulado', '1', '17', 'Clínica Médica', 'Choque séptico', 'Difícil', null, null, 'Paciente de 60 anos, com infecção urinária prévia, chega ao PS confuso, PA 80x50mmHg, FC 130bpm, febre de 39°C, extremidades quentes. Lactato elevado. Qual a conduta inicial mais adequada?', 'Iniciar vasopressor isolado, sem reposição volêmica prévia', 'Aguardar resultado de hemocultura antes de iniciar qualquer antibiótico', 'Reposição volêmica agressiva com cristaloide, coleta de culturas e início precoce de antibiótico de amplo espectro', 'Alta com antibiótico oral e retorno se piora', 'C', 'Choque séptico exige reposição volêmica precoce com cristaloide, coleta de culturas antes (mas sem atrasar) o início de antibiótico de amplo espectro na primeira hora.', 'A: vasopressor geralmente é iniciado após ou concomitante à reposição volêmica inicial. B: atrasar o antibiótico aguardando cultura aumenta a mortalidade em sepse. D: sinais de choque contraindicam alta hospitalar.', 'Em revisão'),
  ('SIM1-018', 'simulado', '1', '18', 'Clínica Médica', 'Dengue - classificação de gravidade', 'Médio', null, null, 'Paciente com quadro compatível com dengue há 4 dias, apresenta dor abdominal intensa, vômitos persistentes e letargia, sem sangramento evidente. Qual a classificação e conduta mais adequada?', 'Dengue com sinais de alarme; internação para hidratação venosa e monitorização', 'Dengue grave; não requer conduta diferenciada da forma sem sinais de alarme', 'Não é dengue, pois ausência de sangramento exclui o diagnóstico', 'Dengue sem sinais de alarme; alta com orientações e retorno se necessário', 'A', 'Dor abdominal intensa, vômitos persistentes e letargia são sinais de alarme para dengue, indicando necessidade de internação para hidratação venosa e monitorização rigorosa.', 'B: dengue grave exige conduta ainda mais intensiva. C: sangramento não é obrigatório para o diagnóstico de dengue. D: os sinais descritos são de alarme, contraindicando conduta ambulatorial isolada.', 'Em revisão'),
  ('SIM1-019', 'simulado', '1', '19', 'Clínica Médica', 'Hanseníase - diagnóstico e classificação', 'Médio', null, null, 'Paciente apresenta manchas hipocrômicas com alteração de sensibilidade térmica e dolorosa na pele, além de espessamento de nervo periférico palpável. Qual a hipótese diagnóstica mais provável e conduta?', 'Micose superficial; iniciar antifúngico tópico', 'Hanseníase; classificar (paucibacilar ou multibacilar) e iniciar poliquimioterapia específica', 'Vitiligo; encaminhar para acompanhamento dermatológico estético', 'Dermatite atópica; iniciar corticoide tópico', 'B', 'Lesões de pele com alteração de sensibilidade associadas a espessamento de nervo periférico são características de hanseníase; a conduta é classificar a forma clínica e iniciar poliquimioterapia.', 'A e D: não explicam a alteração de sensibilidade nem o comprometimento neural. C: vitiligo não causa alteração de sensibilidade nem espessamento de nervos.', 'Em revisão'),
  ('SIM1-020', 'simulado', '1', '20', 'Clínica Médica', 'Doença de Chagas - fase crônica cardíaca', 'Difícil', null, null, 'Paciente de 50 anos, natural de área endêmica, sorologia positiva para Trypanosoma cruzi, apresenta palpitações e ECG com bloqueio de ramo direito associado a hemibloqueio anterior esquerdo. Qual a fase da doença e conduta mais adequada?', 'Fase crônica cardíaca; avaliação cardiológica completa (ecocardiograma, Holter) e tratamento das complicações', 'Fase aguda; iniciar benzonidazol como única conduta necessária', 'Doença não relacionada a Chagas, pois sorologia positiva isolada não tem significado clínico', 'Fase indeterminada; não é necessária nenhuma avaliação adicional', 'A', 'Alterações eletrocardiográficas típicas (BRD + HBAE) em paciente com sorologia positiva indicam fase crônica cardíaca da doença de Chagas, exigindo avaliação cardiológica completa.', 'B: fase aguda tem apresentação clínica diferente. C: sorologia positiva com alterações compatíveis tem, sim, significado clínico relevante. D: fase indeterminada não apresenta alterações cardíacas; este caso já mostra comprometimento.', 'Em revisão'),
  ('SIM1-021', 'simulado', '1', '21', 'Clínica Médica', 'Hepatite B - interpretação sorológica', 'Difícil', null, null, 'Paciente assintomático realiza sorologia de rotina: HBsAg positivo, Anti-HBc IgG positivo, HBeAg negativo, Anti-HBe positivo, transaminases normais, carga viral baixa. Qual a interpretação mais adequada?', 'Hepatite B aguda; iniciar tratamento antiviral imediato', 'Hepatite B crônica ativa; iniciar antiviral de forma obrigatória', 'Imunidade vacinal; não há necessidade de acompanhamento', 'Estado de portador inativo do HBsAg; acompanhamento periódico sem tratamento antiviral imediato', 'D', 'HBsAg positivo com HBeAg negativo, Anti-HBe positivo, transaminases normais e carga viral baixa sugerem estado de portador inativo, que requer acompanhamento periódico sem tratamento antiviral imediato.', 'A: hepatite aguda cursaria com IgM anti-HBc positivo e quadro clínico compatível. B: hepatite crônica ativa geralmente cursa com transaminases elevadas e/ou carga viral alta, ausentes aqui. C: imunidade vacinal cursaria com Anti-HBs positivo isolado, não HBsAg positivo.', 'Em revisão'),
  ('SIM1-022', 'simulado', '1', '22', 'Clínica Médica', 'Hipertireoidismo - Doença de Graves', 'Médio', null, null, 'Paciente de 30 anos com perda de peso, taquicardia, tremores, exoftalmia e bócio difuso. TSH suprimido, T4 livre elevado. Qual a hipótese diagnóstica mais provável e conduta inicial?', 'Tireoidite subaguda; apenas anti-inflamatório, sem necessidade de outro tratamento', 'Doença de Graves; iniciar tionamida (ex: metimazol) e betabloqueador para controle sintomático', 'Nódulo tireoidiano isolado; encaminhar para biópsia sem tratamento medicamentoso inicial', 'Hipotireoidismo; iniciar levotiroxina', 'B', 'Exoftalmia, bócio difuso e hipertireoidismo laboratorial sugerem doença de Graves; o tratamento inicial envolve tionamida e betabloqueador para controle dos sintomas adrenérgicos.', 'A: tireoidite subaguda geralmente cursa com dor cervical e é autolimitada. C: exoftalmia e bócio difuso não são compatíveis com nódulo isolado. D: quadro é de hipertireoidismo, não hipotireoidismo.', 'Em revisão'),
  ('SIM1-023', 'simulado', '1', '23', 'Clínica Médica', 'Pancreatite aguda', 'Médio', null, null, 'Paciente de 45 anos, etilista, apresenta dor abdominal intensa em faixa, irradiando para o dorso, associada a náuseas e vômitos. Amilase e lipase séricas elevadas (>3x o valor normal). Qual a conduta inicial mais adequada?', 'Antibioticoterapia profilática de rotina para todos os casos', 'Cirurgia de urgência imediata, independente da gravidade', 'Jejum, hidratação venosa vigorosa e analgesia, com monitorização de gravidade', 'Dieta hiperproteica imediata para recuperação nutricional', 'C', 'Pancreatite aguda tem manejo inicial conservador: jejum, hidratação venosa vigorosa, analgesia adequada e monitorização de sinais de gravidade.', 'A: antibiótico profilático de rotina não é recomendado para todos os casos. B: cirurgia é reservada para complicações específicas, não é conduta inicial. D: dieta hiperproteica imediata pode agravar a inflamação pancreática.', 'Em revisão'),
  ('SIM1-024', 'simulado', '1', '24', 'Clínica Médica', 'Embolia pulmonar - probabilidade clínica', 'Difícil', null, null, 'Paciente de 55 anos, pós-operatório de cirurgia ortopédica há 5 dias, apresenta dispneia súbita, dor torácica pleurítica e taquicardia. Escore de Wells sugere probabilidade alta de embolia pulmonar. Qual a conduta mais adequada?', 'Aguardar D-dímero antes de qualquer conduta, mesmo com alta probabilidade clínica', 'Iniciar anticoagulação empírica e solicitar angiotomografia de tórax para confirmação diagnóstica', 'Trombólise sistêmica imediata sem confirmação diagnóstica em paciente estável', 'Alta hospitalar com anti-inflamatório, pois dor pleurítica é geralmente benigna', 'B', 'Em paciente com alta probabilidade clínica de embolia pulmonar, deve-se iniciar anticoagulação empírica enquanto se confirma o diagnóstico com angiotomografia.', 'A: D-dímero tem valor limitado em pacientes de alta probabilidade clínica. C: trombólise sistêmica é reservada para EP maciça com instabilidade hemodinâmica. D: o quadro é sugestivo de doença potencialmente grave.', 'Em revisão'),
  ('SIM1-025', 'simulado', '1', '25', 'Clínica Médica', 'Meningite bacteriana', 'Difícil', null, null, 'Paciente de 25 anos apresenta febre alta, cefaleia intensa, rigidez de nuca e fotofobia há 12 horas, com rebaixamento leve do nível de consciência. Qual a conduta inicial mais adequada?', 'Iniciar antibioticoterapia empírica imediatamente, sem aguardar exames confirmatórios, e realizar punção lombar assim que possível', 'Solicitar ressonância magnética antes de qualquer conduta terapêutica', 'Aguardar resultado de punção lombar antes de iniciar qualquer antibiótico', 'Iniciar apenas analgesia e observação, pois o quadro pode ser enxaqueca', 'A', 'Suspeita de meningite bacteriana é emergência médica; a antibioticoterapia empírica deve ser iniciada imediatamente, sem aguardar confirmação laboratorial.', 'B: RM não deve atrasar o início do tratamento. C: atrasar antibiótico aguardando punção lombar aumenta significativamente a mortalidade. D: os sinais não são compatíveis com enxaqueca simples.', 'Em revisão'),
  ('SIM1-026', 'simulado', '1', '26', 'Clínica Médica', 'Leptospirose', 'Médio', null, null, 'Paciente que trabalha em área de enchente recente apresenta febre, mialgia intensa (especialmente em panturrilhas), icterícia e sufusão conjuntival. Qual a hipótese diagnóstica mais provável e conduta?', 'Leptospirose; iniciar antibioticoterapia precoce e monitorar função renal/hepática', 'Dengue clássica; apenas hidratação oral', 'Hepatite viral aguda isolada; apenas suporte clínico', 'Infecção urinária; iniciar antibiótico oral ambulatorial', 'A', 'Mialgia intensa em panturrilhas, icterícia, sufusão conjuntival e exposição a áreas alagadas são sugestivos de leptospirose; iniciar antibioticoterapia precoce e monitorar função renal/hepática.', 'B: dengue não costuma cursar com icterícia e sufusão conjuntival típicas. C: hepatite viral isolada não explica a mialgia intensa nem a sufusão conjuntival característica. D: quadro sistêmico grave não deve ser tratado apenas como infecção urinária ambulatorial.', 'Em revisão'),
  ('SIM1-027', 'simulado', '1', '27', 'Clínica Médica', 'Síndrome metabólica', 'Médio', null, null, 'Paciente de 48 anos com circunferência abdominal aumentada, PA 145x92mmHg, glicemia de jejum 110mg/dL, triglicerídeos elevados e HDL baixo. Qual a conduta mais adequada?', 'Indicar cirurgia bariátrica como primeira conduta', 'Iniciar estatina em dose máxima imediatamente, independentemente de outros fatores de risco', 'Nenhuma conduta é necessária, pois os valores estão apenas discretamente alterados', 'Diagnóstico de síndrome metabólica; orientar mudança de estilo de vida e tratar os componentes individuais conforme indicado', 'D', 'A combinação de obesidade abdominal, PA elevada, glicemia alterada e dislipidemia caracteriza síndrome metabólica; a conduta inicial é mudança de estilo de vida associada ao tratamento individualizado.', 'A: cirurgia bariátrica é reservada para casos específicos. B: estatina em dose máxima sem avaliação individualizada não é a conduta inicial padrão. C: a combinação de fatores de risco justifica intervenção ativa.', 'Em revisão'),
  ('SIM1-028', 'simulado', '1', '28', 'Clínica Médica', 'DPOC vs Asma - diagnóstico diferencial', 'Médio', null, null, 'Paciente de 55 anos, ex-tabagista, com dispneia crônica progressiva e tosse. Espirometria mostra relação VEF1/CVF reduzida, sem resposta significativa ao broncodilatador. Qual o diagnóstico mais provável e a característica que o diferencia da asma?', 'DPOC; a obstrução ao fluxo aéreo é predominantemente irreversível, diferente da reversibilidade típica da asma', 'Asma; a obstrução é sempre parcialmente irreversível, igual à DPOC', 'Bronquite aguda; quadro autolimitado sem necessidade de espirometria', 'Ambas as doenças têm o mesmo padrão espirométrico e não podem ser diferenciadas', 'A', 'O padrão obstrutivo com pouca resposta ao broncodilatador, associado a tabagismo e dispneia progressiva, é característico de DPOC — obstrução predominantemente fixa, ao contrário da asma.', 'B: reversibilidade significativa aproxima do diagnóstico de asma, não de DPOC. C: quadro crônico e progressivo não é compatível com bronquite aguda autolimitada. D: os padrões podem ser diferenciados pela resposta ao broncodilatador.', 'Em revisão'),
  ('SIM1-029', 'simulado', '1', '29', 'Ginecologia e Obstetrícia', 'Síndromes hipertensivas da gestação', 'Médio', null, null, 'Gestante de 32 semanas, primigesta, comparece à UBS com PA 158x102mmHg em duas aferições, edema de membros inferiores e proteinúria de fita 2+. Nega cefaleia, escotomas ou dor epigástrica. Qual a conduta inicial mais adequada?', 'Tranquilizar a paciente e agendar retorno em 30 dias, pois não há sintomas de gravidade', 'Prescrever anti-hipertensivo oral e liberar para acompanhamento apenas na UBS', 'Encaminhar para maternidade de referência para avaliação e conduta especializada', 'Indicar interrupção imediata da gestação, independentemente da idade gestacional', 'C', 'Critérios de pré-eclâmpsia (PA≥140/90 + proteinúria) exigem encaminhamento a serviço de referência para avaliação de gravidade, exames complementares (função renal, hepática, plaquetas) e definição de conduta obstétrica.', 'A: subestima o risco; a pré-eclâmpsia pode evoluir rapidamente. B: tratar apenas a PA não maneja a doença de base nem monitora complicações. D: a interrupção não é automática, depende da gravidade e da idade gestacional, avaliadas em serviço especializado.', 'Em revisão'),
  ('SIM1-030', 'simulado', '1', '30', 'Ginecologia e Obstetrícia', 'Gravidez ectópica / abdome agudo na gestação', 'Difícil', null, null, 'Mulher de 27 anos, atraso menstrual de 7 semanas, dá entrada no PS com dor pélvica súbita em fossa ilíaca direita e sangramento vaginal discreto. PA 90x60mmHg, FC 118bpm, abdome doloroso à palpação com defesa em FID. Beta-hCG positivo. Qual a hipótese diagnóstica mais provável e a conduta inicial?', 'Gravidez ectópica rota; estabilização hemodinâmica seguida de cirurgia de urgência', 'Doença inflamatória pélvica; iniciar antibioticoterapia empírica', 'Cisto de ovário roto; conduta expectante com analgesia', 'Abortamento incompleto; realizar curetagem uterina de urgência', 'A', 'Atraso menstrual + beta-hCG positivo + dor abdominal aguda + instabilidade hemodinâmica sugerem gravidez ectópica rota, emergência cirúrgica. A prioridade é estabilização (acesso venoso calibroso, reposição volêmica) seguida de intervenção cirúrgica imediata.', 'B: DIP não explica beta-hCG positivo nem a instabilidade hemodinâmica aguda. C: conduta expectante é inadequada diante de sinais de choque hipovolêmico. D: não há evidência de gestação intrauterina/abortamento; os achados apontam para ectópica.', 'Em revisão'),
  ('SIM1-031', 'simulado', '1', '31', 'Ginecologia e Obstetrícia', 'Distócia / partograma', 'Difícil', null, null, 'Gestante de 39 semanas, em trabalho de parto, com dilatação cervical estacionada em 6cm há 4 horas apesar de contrações regulares e efetivas, membranas rotas, apresentação cefálica insinuada. O partograma mostra a curva de dilatação ultrapassando a linha de ação. Qual a conduta mais adequada?', 'Aguardar evolução espontânea por mais 4 horas antes de qualquer intervenção', 'Indicar cesariana imediata sem avaliação adicional', 'Avaliar proporção céfalo-pélvica e considerar ocitocina ou via de parto conforme a avaliação', 'Realizar manobra de Kristeller para acelerar a descida fetal', 'C', 'Parada de progressão com curva ultrapassando a linha de ação indica distócia funcional; a conduta é avaliar a adequação da bacia/apresentação e, na ausência de desproporção, considerar correção da dinâmica uterina (ocitocina) antes de indicar cesariana.', 'A: atraso na intervenção aumenta o risco materno-fetal. B: cesariana sem avaliação prévia é precipitada. D: a manobra de Kristeller é contraindicada pelo risco de lesões materno-fetais.', 'Em revisão'),
  ('SIM1-032', 'simulado', '1', '32', 'Ginecologia e Obstetrícia', 'Diabetes mellitus gestacional', 'Médio', null, null, 'Gestante de 26 semanas realiza teste oral de tolerância à glicose (TOTG 75g) com os seguintes valores: jejum 95 mg/dL, 1h 185 mg/dL, 2h 155 mg/dL. Qual a interpretação e conduta mais adequada?', 'Resultado inconclusivo; repetir o exame em 4 semanas sem qualquer orientação', 'Resultado normal; manter apenas o pré-natal de rotina', 'Diagnóstico de diabetes mellitus gestacional; iniciar orientação nutricional e monitorização glicêmica', 'Diagnóstico de diabetes mellitus prévio à gestação; iniciar insulina em dose plena imediatamente', 'C', 'Valores de jejum ≥92, 1h ≥180 ou 2h ≥153 mg/dL no TOTG confirmam diabetes gestacional; a conduta inicial é orientação nutricional e monitorização glicêmica, com insulina reservada para casos sem controle adequado com dieta.', 'A: o resultado já é diagnóstico, não é inconclusivo. B: os valores excedem os pontos de corte diagnósticos, não é resultado normal. D: diabetes prévio à gestação é diagnosticado por critérios diferentes; insulina não é primeira conduta sem tentativa de controle dietético.', 'Em revisão'),
  ('SIM1-033', 'simulado', '1', '33', 'Ginecologia e Obstetrícia', 'Climatério - terapia hormonal', 'Médio', null, null, 'Mulher de 52 anos, sem menstruar há 14 meses, relata fogachos intensos e sudorese noturna que afetam sua qualidade de vida. Nega histórico pessoal de câncer de mama, tromboembolismo ou doença hepática. Qual a conduta mais adequada?', 'Terapia hormonal sistêmica (estrogênio + progestagênio, já que possui útero), após avaliação de riscos e benefícios', 'Nenhum tratamento é indicado, pois sintomas climatéricos não podem ser tratados', 'Ooforectomia bilateral para eliminar a produção hormonal residual', 'Antibioticoterapia para tratar os sintomas vasomotores', 'A', 'Na ausência de contraindicações (câncer de mama, TEV, doença hepática), a terapia hormonal é a opção mais eficaz para sintomas vasomotores moderados a intensos no climatério; como a paciente tem útero, é necessário associar progestagênio ao estrogênio para proteção endometrial.', 'B: existem tratamentos eficazes e a paciente tem indicação clara pela intensidade dos sintomas. C: cirurgia não é indicada apenas para tratar sintomas climatéricos. D: antibiótico não tem relação com o mecanismo dos sintomas vasomotores.', 'Em revisão'),
  ('SIM1-034', 'simulado', '1', '34', 'Ginecologia e Obstetrícia', 'Sangramento uterino anormal - investigação', 'Médio', null, null, 'Mulher de 42 anos relata sangramento menstrual intenso e prolongado há 3 ciclos, sem dor associada. Exame especular sem lesões visíveis, útero de tamanho normal à palpação. Qual a conduta inicial mais adequada?', 'Solicitar ultrassonografia transvaginal e avaliação laboratorial (hemograma, função tireoidiana) para investigar a causa', 'Tranquilizar a paciente, pois sangramento irregular nessa idade é sempre fisiológico', 'Indicar histerectomia diretamente, sem investigação prévia', 'Prescrever apenas anticoncepcional hormonal combinado, sem investigação adicional', 'A', 'Sangramento uterino anormal em mulher de 42 anos requer investigação estruturada (USG transvaginal para avaliar estrutura uterina/endométrio, exames laboratoriais para causas sistêmicas) antes de definir a conduta terapêutica.', 'B: sangramento anormal não deve ser assumido como fisiológico sem investigação, especialmente pelo risco de causas estruturais/neoplásicas. C: histerectomia é conduta definitiva que não deve ser indicada sem diagnóstico prévio. D: tratamento hormonal empírico sem investigação pode mascarar uma causa importante.', 'Em revisão'),
  ('SIM1-035', 'simulado', '1', '35', 'Ginecologia e Obstetrícia', 'Rotura prematura de membranas pré-termo', 'Difícil', null, null, 'Gestante de 32 semanas relata perda de líquido claro pela vagina há 2 horas, sem contrações. Exame especular confirma saída de líquido amniótico pelo colo. Ausência de sinais de infecção (afebril, sem taquicardia materna ou fetal). Qual a conduta mais adequada?', 'Conduta expectante com internação, corticoterapia para maturação pulmonar fetal e vigilância de sinais de infecção', 'Indicar parto imediato por via alta, independentemente da idade gestacional', 'Alta hospitalar com orientação de retorno apenas se houver febre', 'Iniciar antibioticoterapia de amplo espectro e aguardar o trabalho de parto espontâneo em casa', 'A', 'Na rotura prematura de membranas pré-termo sem sinais de infecção ou sofrimento fetal, a conduta é conservadora: internação, corticoterapia para maturação pulmonar fetal e vigilância rigorosa de sinais de corioamnionite, buscando prolongar a gestação com segurança.', 'B: interrupção imediata da gestação sem indicação materna/fetal aumenta a prematuridade desnecessariamente. C: alta domiciliar não permite vigilância adequada de sinais de infecção/sofrimento fetal. D: antibiótico empírico e acompanhamento domiciliar não são condutas padrão nesse cenário.', 'Em revisão'),
  ('SIM1-036', 'simulado', '1', '36', 'Ginecologia e Obstetrícia', 'Planejamento familiar - escolha de método contraceptivo', 'Difícil', null, null, 'Mulher de 30 anos, tabagista, procura a UBS para orientação contraceptiva. Relata enxaqueca com aura ocasional. Qual método contraceptivo é mais adequado considerando suas características?', 'Nenhum método é seguro; deve-se orientar apenas abstinência', 'Anel vaginal combinado, pois evita o metabolismo hepático de primeira passagem', 'Método contraceptivo apenas de progestagênio (ex: DIU hormonal ou minipílula) ou método não hormonal', 'Anticoncepcional oral combinado (estrogênio + progestagênio)', 'C', 'Enxaqueca com aura é contraindicação para métodos com estrogênio (risco aumentado de AVC), independente da idade; a tabagista com enxaqueca com aura deve usar métodos apenas de progestagênio ou não hormonais.', 'A: existem opções seguras e eficazes sem necessidade de abstinência. B: anel vaginal combinado também contém estrogênio, mesma contraindicação se aplica. D: contraindicado pelo risco vascular aumentado com estrogênio na presença de enxaqueca com aura.', 'Em revisão'),
  ('SIM1-037', 'simulado', '1', '37', 'Ginecologia e Obstetrícia', 'Placenta prévia', 'Médio', null, null, 'Gestante de 34 semanas apresenta sangramento vaginal vermelho vivo, indolor, sem contrações. Ultrassonografia confirma placenta recobrindo totalmente o orifício interno do colo. Qual a conduta mais adequada?', 'Toque vaginal para avaliar dilatação antes de qualquer conduta', 'Indicar parto vaginal imediato, independentemente da localização placentária', 'Conduta expectante com internação se sangramento importante, evitando toque vaginal, e via de parto cesariana planejada', 'Alta hospitalar com repouso domiciliar absoluto, sem necessidade de reavaliação', 'C', 'Placenta prévia total contraindica toque vaginal; a conduta é expectante (se sangramento controlável), com via de parto cesariana planejada devido à obstrução do canal de parto.', 'A: toque vaginal é contraindicado pelo risco de hemorragia grave. B: parto vaginal é contraindicado quando a placenta recobre totalmente o orifício interno. D: sangramento ativo requer avaliação e possível internação.', 'Em revisão'),
  ('SIM1-038', 'simulado', '1', '38', 'Ginecologia e Obstetrícia', 'Descolamento prematuro de placenta', 'Difícil', null, null, 'Gestante de 36 semanas, hipertensa, apresenta dor abdominal súbita e intensa, sangramento vaginal escuro em pequena quantidade, útero hipertônico à palpação, e sofrimento fetal ao monitoramento. Qual a hipótese diagnóstica e conduta mais adequada?', 'Trabalho de parto normal; acompanhar a evolução sem intervenção', 'Placenta prévia; conduta expectante ambulatorial', 'Descolamento prematuro de placenta; interrupção imediata da gestação, geralmente por via cesariana de urgência', 'Rotura uterina; aguardar exame de imagem antes de qualquer conduta', 'C', 'Dor abdominal súbita, útero hipertônico, sangramento escuro e sofrimento fetal em gestante hipertensa são clássicos de descolamento prematuro de placenta, exigindo interrupção imediata da gestação.', 'A: o quadro não é de trabalho de parto normal, mas de emergência obstétrica. B: placenta prévia cursa tipicamente com sangramento vermelho vivo indolor, sem hipertonia uterina. D: a gravidade do quadro não permite aguardar exame de imagem.', 'Em revisão'),
  ('SIM1-039', 'simulado', '1', '39', 'Ginecologia e Obstetrícia', 'Amenorreia secundária - investigação', 'Médio', null, null, 'Mulher de 28 anos relata ausência de menstruação há 4 meses, sem uso de método contraceptivo hormonal. Beta-hCG negativo. Qual a conduta inicial mais adequada para investigação?', 'Tranquilizar a paciente, pois amenorreia secundária nunca tem causa patológica', 'Investigação hormonal (TSH, prolactina, FSH/LH) e avaliação de causas estruturais/funcionais', 'Iniciar reposição hormonal empírica sem investigação prévia', 'Indicar histerectomia para investigação diagnóstica', 'B', 'Amenorreia secundária com beta-hCG negativo requer investigação estruturada, incluindo avaliação hormonal para identificar causas endócrinas, além de avaliação de causas estruturais.', 'A: amenorreia secundária pode ter diversas causas patológicas que precisam ser investigadas. C: tratamento hormonal empírico sem diagnóstico pode mascarar a causa de base. D: histerectomia não é procedimento diagnóstico apropriado.', 'Em revisão'),
  ('SIM1-040', 'simulado', '1', '40', 'Ginecologia e Obstetrícia', 'Câncer de colo uterino - lesões precursoras', 'Difícil', null, null, 'Paciente com citologia oncótica alterada (lesão intraepitelial de alto grau) é encaminhada para colposcopia, que confirma achados compatíveis com neoplasia intraepitelial cervical grau 3 (NIC 3). Qual a conduta mais adequada?', 'Exérese da zona de transformação (conização) para tratamento e diagnóstico histológico definitivo', 'Indicar histerectomia radical imediatamente, sem confirmação histológica adicional', 'Repetir apenas a citologia em 1 ano, sem outra conduta', 'Tranquilizar a paciente, pois NIC 3 regride espontaneamente na maioria dos casos e não requer conduta', 'A', 'NIC 3 é lesão precursora de alto grau com risco significativo de progressão; a conduta padrão é a exérese da zona de transformação (conização), que trata e fornece material para confirmação histológica.', 'B: histerectomia radical é excessiva para lesão intraepitelial. C: NIC 3 não deve ser apenas acompanhada, devido ao risco de progressão. D: NIC 3 tem baixa taxa de regressão espontânea e alto potencial de progressão.', 'Em revisão'),
  ('SIM1-041', 'simulado', '1', '41', 'Ginecologia e Obstetrícia', 'Doença inflamatória pélvica', 'Médio', null, null, 'Mulher de 24 anos apresenta dor pélvica há 3 dias, corrimento vaginal purulento, febre e dor à mobilização do colo uterino ao exame ginecológico. Qual a hipótese diagnóstica mais provável e conduta?', 'Apendicite aguda; indicar cirurgia imediata sem outra avaliação', 'Endometriose; iniciar apenas analgesia sintomática', 'Cistite simples; iniciar antibiótico de curso curto para infecção urinária', 'Doença inflamatória pélvica; iniciar antibioticoterapia empírica cobrindo os principais agentes envolvidos', 'D', 'Dor pélvica, corrimento purulento, febre e dor à mobilização do colo são característicos de DIP; a conduta é antibioticoterapia empírica cobrindo os principais agentes.', 'A: o quadro aponta mais para DIP; cirurgia imediata sem avaliação adequada não é correta aqui. B: endometriose tem quadro mais crônico e cíclico, sem febre. C: cistite não costuma causar dor à mobilização do colo nem corrimento purulento típico.', 'Em revisão'),
  ('SIM1-042', 'simulado', '1', '42', 'Ginecologia e Obstetrícia', 'Endometriose', 'Difícil', null, null, 'Mulher de 30 anos relata dismenorreia progressiva e intensa, dispareunia de profundidade e infertilidade há 1 ano. Exame físico com nodularidade dolorosa em fundo de saco posterior. Qual a hipótese diagnóstica mais provável e conduta inicial?', 'Miomatose uterina; indicar cirurgia imediata sem tentativa de tratamento clínico', 'Endometriose; considerar tratamento clínico (hormonal) inicial e investigação adicional conforme gravidade dos sintomas/desejo reprodutivo', 'Vaginose bacteriana; iniciar metronidazol', 'Gravidez ectópica; solicitar beta-hCG e conduta cirúrgica de urgência', 'B', 'Dismenorreia progressiva, dispareunia profunda, infertilidade e nodularidade em fundo de saco posterior são sugestivos de endometriose; a conduta inicial costuma ser tratamento clínico hormonal.', 'A: miomatose não costuma causar nodularidade em fundo de saco posterior. C: vaginose não explica dismenorreia progressiva ou nodularidade pélvica. D: não há dados sugestivos de gestação no caso.', 'Em revisão'),
  ('SIM1-043', 'simulado', '1', '43', 'Ginecologia e Obstetrícia', 'Miomatose uterina - conduta', 'Médio', null, null, 'Mulher de 38 anos relata sangramento menstrual intenso e sensação de peso pélvico. USG identifica múltiplos miomas submucosos, sem desejo reprodutivo futuro. Qual a conduta mais adequada?', 'Discutir opções terapêuticas conforme sintomas e desejo da paciente, incluindo tratamento clínico, miomectomia ou histerectomia', 'Iniciar apenas anticoncepcional oral combinado, sem outras considerações', 'Indicar histerectomia como única opção possível, sem discutir alternativas', 'Conduta expectante obrigatória, sem qualquer tratamento, independente dos sintomas', 'A', 'O manejo de miomatose sintomática deve ser individualizado, considerando gravidade dos sintomas, localização dos miomas e desejo reprodutivo.', 'B: anticoncepcional isolado pode não ser suficiente para miomas submucosos sintomáticos importantes. C: histerectomia não é a única opção; alternativas devem ser discutidas. D: sintomas significativos justificam intervenção.', 'Em revisão'),
  ('SIM1-044', 'simulado', '1', '44', 'Ginecologia e Obstetrícia', 'Assistência pré-natal - exames de rotina', 'Fácil', null, null, 'Gestante de 8 semanas realiza sua primeira consulta de pré-natal na UBS. Segundo o protocolo do Ministério da Saúde, qual conjunto de exames deve ser solicitado na primeira consulta?', 'Nenhum exame é necessário antes da 20ª semana de gestação', 'Apenas exame de urina tipo I, sem necessidade de sorologias', 'Apenas hemograma e glicemia de jejum', 'Tipagem sanguínea/Rh, hemograma, glicemia de jejum, sorologias (HIV, sífilis, hepatite B, toxoplasmose), urina tipo I e urocultura', 'D', 'O protocolo de pré-natal recomenda, na primeira consulta, um conjunto amplo de exames para rastreio precoce de condições que impactam o desfecho gestacional.', 'A: exames devem ser solicitados desde a primeira consulta. B: sorologias são essenciais desde o início do pré-natal. C: conjunto incompleto, deixa de rastrear infecções importantes.', 'Em revisão'),
  ('SIM1-045', 'simulado', '1', '45', 'Ginecologia e Obstetrícia', 'Hemorragia pós-parto - atonia uterina', 'Difícil', null, null, 'Puérpera apresenta sangramento vaginal abundante 30 minutos após parto vaginal, com útero amolecido e mal contraído à palpação (atonia uterina). Qual a conduta inicial mais adequada?', 'Aguardar resolução espontânea, pois sangramento pós-parto é sempre autolimitado', 'Massagem uterina bimanual e uso de uterotônicos (ex: ocitocina), com avaliação de outras causas se não houver resposta', 'Alta hospitalar com orientação de retorno se o sangramento persistir', 'Histerectomia imediata, sem tentativa de medidas conservadoras', 'B', 'A atonia uterina é a causa mais comum de hemorragia pós-parto; a conduta inicial envolve massagem uterina bimanual e uterotônicos, progredindo para outras medidas se não houver resposta.', 'A: hemorragia pós-parto pode levar a choque hipovolêmico rapidamente. C: sangramento volumoso ativo contraindica alta hospitalar. D: histerectomia é medida de última linha.', 'Em revisão'),
  ('SIM1-046', 'simulado', '1', '46', 'Ginecologia e Obstetrícia', 'Vulvovaginites - candidíase', 'Fácil', null, null, 'Mulher relata corrimento vaginal branco, grumoso, com prurido intenso, sem odor característico. Exame a fresco mostra hifas. Qual o diagnóstico mais provável e tratamento indicado?', 'Clamídia; azitromicina em dose única', 'Candidíase vulvovaginal; antifúngico tópico ou oral (ex: fluconazol)', 'Vaginose bacteriana; metronidazol oral ou vaginal', 'Tricomoníase; metronidazol com tratamento do parceiro obrigatório', 'B', 'Corrimento branco grumoso, prurido intenso e hifas ao exame a fresco são característicos de candidíase vulvovaginal; tratamento com antifúngico tópico ou oral.', 'A: clamídia geralmente é assintomática ou causa corrimento diferente. C: vaginose bacteriana cursa com corrimento acinzentado, odor fétido e clue cells, não hifas. D: tricomoníase cursa com corrimento amarelo-esverdeado espumoso e protozoário móvel.', 'Em revisão'),
  ('SIM1-047', 'simulado', '1', '47', 'Ginecologia e Obstetrícia', 'Síndrome dos ovários policísticos', 'Médio', null, null, 'Mulher de 24 anos relata ciclos menstruais irregulares, acne e hirsutismo. USG mostra ovários com múltiplos folículos pequenos em disposição periférica. Qual a hipótese diagnóstica mais provável e conduta inicial?', 'Hipotireoidismo isolado; iniciar levotiroxina sem outra investigação', 'Insuficiência ovariana prematura; iniciar reposição hormonal em altas doses imediatamente', 'Síndrome dos ovários policísticos; orientar mudança de estilo de vida e considerar tratamento hormonal conforme sintomas/desejo reprodutivo', 'Gravidez ectópica; solicitar beta-hCG e conduta cirúrgica de urgência', 'C', 'Irregularidade menstrual, hiperandrogenismo clínico e aspecto ovariano policístico à USG sugerem SOP; a conduta inicial inclui mudança de estilo de vida e tratamento hormonal individualizado.', 'A: hipotireoidismo isolado não explica todos os achados. B: insuficiência ovariana prematura cursa com hipoestrogenismo e amenorreia, quadro diferente. D: não há dados sugestivos de gestação no caso.', 'Em revisão'),
  ('SIM1-048', 'simulado', '1', '48', 'Ginecologia e Obstetrícia', 'Aleitamento materno - contraindicações (HIV)', 'Médio', null, null, 'Mãe HIV positivo, em uso regular de terapia antirretroviral com carga viral indetectável, pergunta sobre amamentação do recém-nascido. Qual a orientação mais adequada, segundo as diretrizes brasileiras atuais?', 'Amamentação pode ser considerada apenas se a mãe não usar nenhuma medicação', 'Amamentação é contraindicada; orientar aleitamento artificial exclusivo com fórmula infantil', 'Amamentação mista (leite materno e fórmula) é a opção mais segura', 'Amamentação é obrigatória, independentemente da carga viral materna', 'B', 'No Brasil, a recomendação vigente é que mães vivendo com HIV não amamentem, independentemente da carga viral, devido ao risco de transmissão vertical pelo leite materno.', 'A: a contraindicação independe do uso ou não de medicação materna. C: amamentação mista não elimina o risco de transmissão. D: amamentação não é recomendada em mães HIV positivo no Brasil, mesmo com carga viral indetectável.', 'Em revisão'),
  ('SIM1-049', 'simulado', '1', '49', 'Ginecologia e Obstetrícia', 'Violência sexual - conduta na emergência', 'Difícil', null, null, 'Mulher de 22 anos comparece ao PS relatando violência sexual ocorrida há 3 horas. Qual a conduta mais adequada quanto às profilaxias?', 'Não é necessária nenhuma profilaxia se a paciente não apresentar lesões físicas visíveis', 'Iniciar apenas contracepção de emergência, sem necessidade de profilaxias infecciosas', 'Aguardar boletim de ocorrência policial antes de iniciar qualquer profilaxia', 'Oferecer profilaxia para IST não virais, profilaxia para HIV e contracepção de emergência, respeitando a autonomia da paciente', 'D', 'Em casos de violência sexual, o atendimento não deve ser condicionado a boletim de ocorrência; deve-se oferecer profilaxia para IST não virais, profilaxia para HIV e contracepção de emergência.', 'A: ausência de lesões físicas visíveis não afasta a necessidade de profilaxias. B: profilaxias infecciosas são igualmente importantes. C: o atendimento em saúde não deve ser condicionado à realização de boletim de ocorrência.', 'Em revisão'),
  ('SIM1-050', 'simulado', '1', '50', 'Cirurgia', 'Abdome agudo inflamatório', 'Médio', null, null, 'Paciente de 24 anos com dor abdominal iniciada em região periumbilical há 18 horas, migrando para a fossa ilíaca direita, associada a náuseas e febre baixa. Ao exame: dor à palpação em ponto de McBurney, sinal de Blumberg positivo. Leucocitose com desvio à esquerda. Qual a conduta mais adequada?', 'Solicitar apenas exames laboratoriais seriados por 48h antes de decidir', 'Indicar apendicectomia após avaliação/confirmação diagnóstica', 'Iniciar antibioticoterapia isolada e observar evolução ambulatorial', 'Prescrever analgesia e liberar o paciente, com retorno se houver piora', 'B', 'Quadro clínico clássico de apendicite aguda (dor migratória, sinais de irritação peritoneal, leucocitose) tem indicação cirúrgica; a apendicectomia é o tratamento definitivo, podendo a confirmação ser complementada por exame de imagem em casos duvidosos.', 'A: observação prolongada aumenta o risco de perfuração. C: antibiótico isolado não é conduta padrão fora de protocolos específicos de tratamento não operatório seletivo. D: a alta sem tratamento definitivo expõe o paciente a complicações graves (peritonite).', 'Em revisão'),
  ('SIM1-051', 'simulado', '1', '51', 'Cirurgia', 'Colecistite aguda', 'Médio', null, null, 'Mulher de 45 anos, obesa, com dor em hipocôndrio direito há 2 dias, associada a febre e náuseas. Sinal de Murphy positivo. Ultrassonografia mostra vesícula biliar espessada (>4mm), com cálculos e líquido perivesicular. Qual a conduta mais adequada?', 'Drenagem percutânea da vesícula como único tratamento definitivo', 'Alta hospitalar com analgesia e retorno apenas se houver piora', 'Tratamento clínico exclusivo com antibiótico e colecistectomia eletiva após 6 meses', 'Colecistectomia videolaparoscópica precoce, idealmente dentro das primeiras 72h', 'D', 'Colecistite aguda litiásica confirmada por USG tem indicação de colecistectomia videolaparoscópica precoce (idealmente nas primeiras 72h), associada a menor morbidade e tempo de internação comparado à cirurgia tardia.', 'A: a drenagem percutânea é reservada a pacientes com alto risco cirúrgico, não é tratamento definitivo padrão. B: colecistite aguda não deve ser conduzida apenas ambulatorialmente. C: adiar a cirurgia aumenta o risco de recorrência/complicações antes da cirurgia eletiva.', 'Em revisão'),
  ('SIM1-052', 'simulado', '1', '52', 'Cirurgia', 'Trauma abdominal / atendimento inicial ao politraumatizado', 'Difícil', null, null, 'Paciente vítima de acidente automobilístico chega ao PS com dor abdominal difusa, PA 88x56mmHg, FC 122bpm, abdome distendido e doloroso à palpação. Qual a conduta inicial mais adequada segundo o protocolo de atendimento ao trauma?', 'Iniciar reposição volêmica e realizar FAST (avaliação ultrassonográfica focada em trauma) à beira-leito', 'Aguardar estabilização espontânea antes de qualquer exame', 'Indicar laparotomia exploradora imediata, sem avaliação complementar', 'Solicitar tomografia de abdome antes de qualquer outra medida', 'A', 'Paciente instável com suspeita de trauma abdominal segue o ABCDE do trauma: reposição volêmica imediata e FAST à beira-leito para identificar líquido livre/hemorragia, orientando a necessidade de laparotomia de urgência sem atrasar o atendimento com exames demorados.', 'B: o atraso pode ser fatal diante de sinais de choque. C: laparotomia sem qualquer avaliação, mesmo rápida (como o FAST), pode ser desnecessária ou mal direcionada. D: a TC demanda transporte e tempo, inadequada em paciente instável.', 'Em revisão'),
  ('SIM1-053', 'simulado', '1', '53', 'Cirurgia', 'Hérnia inguinal encarcerada', 'Médio', null, null, 'Paciente de 55 anos com hérnia inguinal direita conhecida há anos apresenta dor intensa e abaulamento irredutível na região inguinal há 6 horas, associado a náuseas. Ao exame, massa dolorosa, tensa, sem sinais de eritema ou toxemia. Qual a conduta mais adequada?', 'Tentativa de redução manual cuidadosa; se sem sucesso ou com sinais de sofrimento, correção cirúrgica de urgência', 'Observação domiciliar com analgesia, pois hérnias encarceradas resolvem espontaneamente', 'Alta com orientação de cirurgia eletiva em 3 meses', 'Aplicação de calor local para reduzir o edema antes de qualquer manipulação', 'A', 'Hérnia encarcerada exige tentativa cuidadosa de redução manual; na falha ou presença de sinais de estrangulamento, a correção cirúrgica de urgência é necessária para evitar isquemia/necrose intestinal.', 'B: encarceramento não resolve espontaneamente e pode evoluir para estrangulamento. C: adiar a cirurgia expõe o paciente a risco de estrangulamento e complicações graves. D: calor local não é conduta indicada e pode mascarar sinais de gravidade.', 'Em revisão'),
  ('SIM1-054', 'simulado', '1', '54', 'Cirurgia', 'Obstrução intestinal', 'Médio', null, null, 'Paciente de 70 anos, com cirurgia abdominal prévia, apresenta dor abdominal em cólica, distensão, parada de eliminação de gases e fezes há 2 dias, associada a vômitos. Radiografia de abdome mostra níveis hidroaéreos e distensão de alças. Qual a conduta inicial mais adequada?', 'Cirurgia de urgência imediata, sem qualquer medida prévia', 'Laxante oral para estimular o trânsito intestinal', 'Descompressão com sonda nasogástrica, reposição hidroeletrolítica e jejum, com reavaliação da necessidade cirúrgica', 'Alta com dieta leve e retorno se piora dos sintomas', 'C', 'Obstrução intestinal mecânica inicialmente é manejada com descompressão nasogástrica, correção hidroeletrolítica e jejum, reservando a cirurgia para sinais de estrangulamento ou falha do tratamento conservador.', 'A: cirurgia imediata sem tentativa de tratamento conservador é excessiva na ausência de sinais de estrangulamento. B: laxante é contraindicado em obstrução mecânica, podendo agravar o quadro. D: sinais de obstrução contraindicam alta e dieta oral.', 'Em revisão'),
  ('SIM1-055', 'simulado', '1', '55', 'Cirurgia', 'Queimaduras - reposição volêmica', 'Difícil', null, null, 'Paciente de 30 anos sofre queimadura de segunda espessura em tronco anterior e todo o membro superior direito. Peso estimado 70 kg. Qual a conduta inicial mais adequada em relação à reposição volêmica, segundo a fórmula de Parkland?', 'Repor volume fixo de 1000 mL de soro fisiológico, independente da superfície queimada', 'Calcular a superfície corporal queimada e repor 4 mL x peso(kg) x %SCQ nas primeiras 24h, com metade nas primeiras 8h', 'Repor apenas por via oral, evitando acesso venoso', 'Restringir líquidos para evitar edema pulmonar', 'B', 'A fórmula de Parkland orienta a reposição volêmica em queimados: 4 mL x peso(kg) x %SCQ de cristaloide nas primeiras 24h, com metade administrada nas primeiras 8h a partir do momento da queimadura.', 'A: volume fixo não considera a extensão da queimadura, subestimando as necessidades do paciente. C: via oral é inadequada para reposição volêmica de grande volume em fase aguda. D: restringir líquidos em queimado extenso pode levar a choque hipovolêmico.', 'Em revisão'),
  ('SIM1-056', 'simulado', '1', '56', 'Cirurgia', 'Nódulo de mama - investigação (BI-RADS)', 'Médio', null, null, 'Mulher de 45 anos identifica nódulo endurecido, indolor, de bordas irregulares na mama direita durante autoexame. Mamografia classificada como BI-RADS 4. Qual a conduta mais adequada?', 'Indicar mastectomia diretamente, sem confirmação histológica prévia', 'Tranquilizar a paciente, pois nódulos indolores raramente são malignos', 'Biópsia da lesão para definição histológica', 'Repetir a mamografia em 1 ano, pois BI-RADS 4 tem baixa suspeita', 'C', 'BI-RADS 4 indica suspeita moderada a alta de malignidade, exigindo biópsia para definição diagnóstica antes de qualquer conduta terapêutica definitiva.', 'A: cirurgia definitiva sem confirmação histológica prévia é inadequada. B: a ausência de dor não exclui malignidade; muitos cânceres de mama são indolores. D: BI-RADS 4 não é de baixa suspeita; requer investigação adicional.', 'Em revisão'),
  ('SIM1-057', 'simulado', '1', '57', 'Cirurgia', 'Hemorragia digestiva alta', 'Difícil', null, null, 'Paciente de 55 anos, etilista, apresenta hematêmese volumosa e melena há 6 horas. PA 90x60mmHg, FC 118bpm, palidez cutânea. Qual a conduta inicial mais adequada?', 'Iniciar apenas inibidor de bomba de prótons oral e observação ambulatorial', 'Endoscopia digestiva alta imediata, antes de qualquer estabilização hemodinâmica', 'Estabilização hemodinâmica (acesso venoso calibroso, reposição volêmica/hemocomponentes) seguida de endoscopia digestiva alta', 'Alta com orientação de retorno se houver nova hematêmese', 'C', 'Paciente com hemorragia digestiva alta e instabilidade hemodinâmica deve ser estabilizado primeiro, e então submetido a endoscopia digestiva alta para diagnóstico e tratamento da causa do sangramento.', 'A: IBP oral e observação ambulatorial são insuficientes diante de instabilidade hemodinâmica. B: realizar endoscopia sem estabilização prévia expõe o paciente a risco durante o procedimento. D: sinais de choque contraindicam alta hospitalar.', 'Em revisão'),
  ('SIM1-058', 'simulado', '1', '58', 'Cirurgia', 'Pancreatite aguda biliar - indicação cirúrgica', 'Difícil', null, null, 'Paciente com pancreatite aguda leve de etiologia biliar (colelitíase identificada em USG), com melhora clínica após tratamento conservador. Qual a conduta mais adequada em relação à colecistectomia?', 'Não há indicação de colecistectomia, apenas acompanhamento clínico', 'Colecistectomia de urgência antes de qualquer tratamento da pancreatite', 'Colecistectomia eletiva após 6 meses, independentemente da gravidade', 'Colecistectomia durante a mesma internação, após resolução do quadro agudo', 'D', 'Na pancreatite aguda biliar leve, recomenda-se a colecistectomia durante a mesma internação, reduzindo o risco de recorrência antes de nova internação.', 'A: a causa biliar identificada deve ser tratada definitivamente. B: cirurgia antes do tratamento/estabilização aumenta o risco cirúrgico. C: adiar para 6 meses aumenta o risco de recorrência.', 'Em revisão'),
  ('SIM1-059', 'simulado', '1', '59', 'Cirurgia', 'Câncer colorretal - sinais de alarme', 'Médio', null, null, 'Paciente de 55 anos relata mudança do hábito intestinal, sangue nas fezes e perda de peso não intencional há 2 meses. Qual a conduta mais adequada?', 'Tranquilizar o paciente, pois esses sintomas são sempre relacionados a hemorroidas', 'Solicitar apenas exame de fezes para parasitas, sem outra investigação', 'Colonoscopia para investigação diagnóstica', 'Prescrever apenas laxante e reavaliar em 6 meses', 'C', 'Sinais de alarme em paciente acima de 50 anos exigem investigação com colonoscopia para descartar neoplasia colorretal, mesmo na presença de hemorroidas concomitantes.', 'A: sinais de alarme não devem ser atribuídos automaticamente a causas benignas sem investigação. B: exame parasitológico não avalia a hipótese de neoplasia colorretal. D: laxante atrasa o diagnóstico de uma possível neoplasia.', 'Em revisão'),
  ('SIM1-060', 'simulado', '1', '60', 'Cirurgia', 'Diverticulite aguda', 'Médio', null, null, 'Paciente de 60 anos apresenta dor em fossa ilíaca esquerda, febre baixa e alteração do hábito intestinal. TC de abdome mostra espessamento da parede do cólon sigmoide com pequena coleção líquida adjacente, sem sinais de perfuração livre. Qual a conduta mais adequada?', 'Alta hospitalar sem tratamento, pois diverticulite é sempre autolimitada', 'Cirurgia de urgência (colectomia) imediata, independentemente da gravidade', 'Colonoscopia imediata para confirmação diagnóstica antes de qualquer tratamento', 'Tratamento clínico com antibioticoterapia e dieta conforme tolerância, com reavaliação da evolução', 'D', 'Diverticulite aguda não complicada é tratada inicialmente de forma clínica, com antibioticoterapia e dieta conforme tolerância, reservando cirurgia para casos complicados.', 'A: diverticulite com sinais de complicação não deve ser deixada sem tratamento. B: cirurgia de urgência é reservada para complicações graves, ausentes neste caso. C: colonoscopia na fase aguda tem risco aumentado de perfuração.', 'Em revisão'),
  ('SIM1-061', 'simulado', '1', '61', 'Cirurgia', 'Politrauma - avaliação primária ABCDE', 'Médio', null, null, 'Vítima de acidente motociclístico chega ao PS com via aérea pérvia, mas com respiração superficial e assimétrica, PA 100x70mmHg, FC 110bpm, Glasgow 14. Qual deve ser a sequência de avaliação inicial mais adequada?', 'Avaliação exclusivamente neurológica primeiro, pelo Glasgow reduzido', 'Avaliação sistematizada ABCDE: via aérea com proteção cervical, respiração/ventilação, circulação com controle de hemorragia, estado neurológico e exposição', 'Solicitar exames de imagem completos antes de qualquer intervenção', 'Aguardar avaliação especializada de cada sistema separadamente, sem sequência definida', 'B', 'O atendimento inicial ao politraumatizado segue a sequência ABCDE, permitindo identificar e tratar rapidamente as condições que ameaçam a vida.', 'A: a avaliação neurológica isolada não identifica problemas mais imediatamente fatais. C: exames de imagem completos não devem atrasar a avaliação inicial. D: a ausência de sequência sistematizada aumenta o risco de não identificar condições fatais.', 'Em revisão'),
  ('SIM1-062', 'simulado', '1', '62', 'Cirurgia', 'Fratura exposta - conduta inicial', 'Médio', null, null, 'Paciente sofre fratura exposta de tíbia após acidente de trânsito, com ferida contaminada por terra. Qual a conduta inicial mais adequada?', 'Aguardar avaliação ortopédica ambulatorial em até 7 dias', 'Redução da fratura no local do acidente antes de qualquer outra medida', 'Cobertura da ferida com curativo estéril, imobilização, antibioticoterapia precoce e profilaxia antitetânica, com encaminhamento para debridamento cirúrgico', 'Apenas limpeza local com água corrente, sem necessidade de antibiótico', 'C', 'Fratura exposta é uma emergência ortopédica; a conduta inicial envolve cobertura estéril, imobilização, antibioticoterapia precoce e profilaxia antitetânica, com debridamento cirúrgico a seguir.', 'A: fratura exposta exige avaliação e tratamento de urgência. B: manipulação/redução no local sem condições adequadas pode agravar lesões associadas. D: a contaminação da ferida exige antibioticoterapia.', 'Em revisão'),
  ('SIM1-063', 'simulado', '1', '63', 'Cirurgia', 'Isquemia mesentérica aguda', 'Difícil', null, null, 'Paciente de 75 anos, com fibrilação atrial sem anticoagulação, apresenta dor abdominal intensa e desproporcional ao exame físico, associada a acidose metabólica. Qual a hipótese diagnóstica mais provável e conduta?', 'Isquemia mesentérica aguda; angiotomografia de urgência e avaliação cirúrgica precoce', 'Constipação intestinal; prescrever laxante e orientar dieta rica em fibras', 'Cólica biliar; apenas analgesia e alta hospitalar', 'Gastrite aguda; iniciar apenas inibidor de bomba de prótons', 'A', 'Dor abdominal desproporcional ao exame físico em paciente com fibrilação atrial associada a acidose metabólica é altamente sugestiva de isquemia mesentérica aguda, exigindo investigação urgente.', 'B: constipação não causa dor desproporcional nem acidose metabólica. C: cólica biliar não costuma cursar com acidose metabólica. D: gastrite não explica a gravidade sistêmica do quadro.', 'Em revisão'),
  ('SIM1-064', 'simulado', '1', '64', 'Cirurgia', 'Torção testicular', 'Difícil', null, null, 'Adolescente de 14 anos apresenta dor testicular súbita e intensa à direita, com edema e testículo elevado e horizontalizado ao exame, sem melhora ao elevar a bolsa escrotal (sinal de Prehn negativo). Qual a conduta mais adequada?', 'Exploração cirúrgica de urgência, sem atraso para exames complementares se a suspeita clínica for alta', 'Aguardar ultrassonografia Doppler antes de qualquer conduta, mesmo com alta suspeita clínica', 'Repouso e analgesia, pois o quadro tende à resolução espontânea em poucos dias', 'Antibioticoterapia oral e retorno em 48 horas para reavaliação', 'A', 'Torção testicular é uma emergência cirúrgica; diante de alta suspeita clínica, a exploração cirúrgica não deve ser atrasada, já que a viabilidade testicular depende do tempo até a correção.', 'B: aguardar imagem quando a suspeita clínica é alta atrasa o tratamento. C: torção não se resolve espontaneamente sem risco de necrose. D: antibiótico é indicado em epididimite/orquite infecciosa, não em torção testicular.', 'Em revisão'),
  ('SIM1-065', 'simulado', '1', '65', 'Cirurgia', 'Nódulo tireoidiano - investigação', 'Médio', null, null, 'Paciente apresenta nódulo tireoidiano palpável de 2cm, identificado ao exame físico. Ultrassonografia classifica o nódulo como TI-RADS 4 (suspeita moderada). Qual a conduta mais adequada?', 'Iniciar levotiroxina para tentar reduzir o tamanho do nódulo', 'Tireoidectomia total imediata, sem confirmação citológica prévia', 'Apenas repetir a ultrassonografia em 2 anos, sem outra conduta', 'Punção aspirativa por agulha fina (PAAF) guiada por ultrassonografia para avaliação citológica', 'D', 'Nódulos TI-RADS 4 e tamanho relevante têm indicação de PAAF guiada por USG para avaliação citológica, definindo a conduta subsequente.', 'A: levotiroxina supressiva não é o tratamento padrão para nódulos com suspeita de malignidade. B: cirurgia definitiva sem confirmação citológica prévia é conduta precipitada. C: a classificação de suspeita moderada não permite apenas seguimento prolongado.', 'Em revisão'),
  ('SIM1-066', 'simulado', '1', '66', 'Cirurgia', 'Úlcera péptica perfurada', 'Difícil', null, null, 'Paciente de 50 anos, em uso crônico de anti-inflamatório, apresenta dor abdominal súbita e intensa em andar superior do abdome, com abdome em tábua (rigidez difusa) e ausência de ruídos hidroaéreos. Radiografia de abdome mostra pneumoperitônio. Qual a conduta mais adequada?', 'Colonoscopia de urgência para diagnóstico complementar antes de qualquer conduta', 'Tratamento clínico exclusivo com inibidor de bomba de prótons, sem necessidade de cirurgia', 'Laparotomia/laparoscopia de urgência para correção da perfuração', 'Alta hospitalar com analgesia oral e retorno se piora', 'C', 'Abdome em tábua com pneumoperitônio confirma perfuração de víscera oca (provável úlcera péptica perfurada); a conduta é cirúrgica de urgência.', 'A: colonoscopia é contraindicada em abdome agudo perfurativo. B: perfuração confirmada com peritonite exige correção cirúrgica. D: quadro de abdome agudo perfurativo contraindica alta hospitalar.', 'Em revisão'),
  ('SIM1-067', 'simulado', '1', '67', 'Cirurgia', 'Pé diabético - avaliação e conduta', 'Médio', null, null, 'Paciente diabético de longa data apresenta úlcera plantar indolor, com bordas calejadas, em região de proeminência óssea do pé, sem sinais de infecção ativa. Qual a conduta mais adequada?', 'Amputação preventiva imediata, independentemente da gravidade da lesão', 'Apenas curativo oclusivo, sem necessidade de avaliação adicional', 'Avaliação vascular e neurológica, desbridamento quando indicado, alívio de pressão local (descarga) e controle glicêmico rigoroso', 'Repouso absoluto sem qualquer intervenção local na ferida', 'C', 'Úlcera neuropática em pé diabético requer avaliação vascular e neurológica, desbridamento quando indicado, alívio da pressão sobre a área e controle glicêmico rigoroso.', 'A: amputação é medida extrema, reservada para casos graves. B: curativo isolado sem avaliação global não trata adequadamente a causa. D: repouso absoluto sem cuidado local adequado não favorece a cicatrização.', 'Em revisão'),
  ('SIM1-068', 'simulado', '1', '68', 'Cirurgia', 'Hemorroidas - conduta clínica', 'Fácil', null, null, 'Paciente relata sangramento vermelho vivo ao evacuar, indolor, associado a prolapso de mucosa anal que retorna espontaneamente após a evacuação. Ao exame proctológico, confirma-se hemorroida interna grau II. Qual a conduta mais adequada?', 'Hemorroidectomia cirúrgica imediata, independentemente do grau', 'Tratamento clínico inicial (dieta rica em fibras, hidratação, higiene local) e medidas conservadoras, reservando procedimentos para casos refratários', 'Nenhuma conduta é necessária, pois hemorroidas nunca requerem tratamento', 'Colonoscopia de urgência antes de qualquer orientação, mesmo com quadro típico', 'B', 'Hemorroidas internas de grau II geralmente respondem a medidas conservadoras, sendo os procedimentos reservados para casos refratários ou graus mais avançados.', 'A: cirurgia não é a primeira conduta para hemorroidas de grau II. C: sintomas presentes justificam orientação e tratamento. D: colonoscopia de urgência não é obrigatória diante de quadro típico.', 'Em revisão'),
  ('SIM1-069', 'simulado', '1', '69', 'Pediatria', 'Diarreia aguda / planos de hidratação', 'Fácil', null, null, 'Criança de 2 anos é trazida à UBS com diarreia líquida há 2 dias, sem sangue, aceitando líquidos por via oral, alerta, olhos sem fundo, sem sinais de desidratação ao exame. Qual a conduta mais adequada segundo o protocolo do Ministério da Saúde?', 'Plano B: hidratação oral supervisionada na unidade de saúde por 4-6 horas', 'Plano C: hidratação venosa imediata', 'Internação hospitalar para observação por 48 horas', 'Plano A: manter alimentação habitual, aumentar oferta de líquidos e SRO em casa, orientar sinais de alarme', 'D', 'Criança sem sinais de desidratação segue o Plano A: manejo domiciliar com aumento da oferta de líquidos, SRO após cada evacuação líquida, manutenção da alimentação e orientação sobre sinais de alarme para retorno.', 'A: o Plano B é indicado para desidratação leve/moderada, ausente neste caso. B: o Plano C (hidratação venosa) é reservado para desidratação grave/choque. C: não há indicação de internação em quadro sem sinais de gravidade.', 'Em revisão'),
  ('SIM1-070', 'simulado', '1', '70', 'Pediatria', 'Sepse neonatal precoce', 'Difícil', null, null, 'Recém-nascido de 18 horas de vida, filho de mãe com bolsa rota há 20 horas antes do parto e sem profilaxia para Streptococcus agalactiae, apresenta-se taquipneico, hipoativo e com temperatura instável. Qual a conduta mais adequada?', 'Alta hospitalar com orientações aos pais sobre sinais de alerta', 'Aguardar resultado da hemocultura antes de iniciar qualquer tratamento', 'Observação clínica ambulatorial, com retorno em 24h', 'Iniciar investigação (hemograma, PCR, hemocultura) e antibioticoterapia empírica precoce', 'D', 'Fatores de risco para sepse neonatal precoce (bolsa rota prolongada, ausência de profilaxia para GBS) associados a sinais clínicos sugestivos (taquipneia, hipoatividade, instabilidade térmica) indicam início imediato de investigação e antibioticoterapia empírica, sem aguardar confirmação laboratorial completa.', 'A: a alta é contraindicada diante de sinais clínicos e fatores de risco significativos. B: aguardar a hemocultura atrasa um tratamento essencial em quadro de alto risco. C: observação ambulatorial expõe o RN a risco de deterioração rápida.', 'Em revisão'),
  ('SIM1-071', 'simulado', '1', '71', 'Pediatria', 'Calendário Nacional de Vacinação', 'Fácil', null, null, 'Mãe leva filho de 4 meses à UBS para consulta de puericultura. A caderneta mostra que a criança recebeu apenas a primeira dose de pentavalente e VIP, aos 2 meses, e não retornou desde então. Qual a conduta mais adequada em relação à vacinação?', 'Reiniciar todo o esquema vacinal desde a primeira dose, pois houve atraso', 'Aplicar as doses atrasadas, retomando o esquema a partir do ponto em que parou, sem reiniciar da primeira dose', 'Aguardar até os 6 meses para retomar o esquema vacinal completo de uma vez', 'Não é possível vacinar crianças com esquema atrasado fora do calendário padrão', 'B', 'Vacinas do calendário nacional não exigem reinício do esquema em caso de atraso; a conduta correta é retomar a partir da dose onde parou, respeitando os intervalos mínimos entre doses, buscando completar o esquema o quanto antes.', 'A: reiniciar do zero não é necessário e atrasa ainda mais a proteção vacinal. C: adiar aumenta o tempo de exposição da criança a doenças imunopreveníveis. D: esquemas atrasados podem e devem ser retomados; é conduta padrão da atenção básica.', 'Em revisão'),
  ('SIM1-072', 'simulado', '1', '72', 'Pediatria', 'Asma - crise aguda na infância', 'Médio', null, null, 'Criança de 6 anos, asmática, é trazida ao PS com falta de ar, tosse e sibilância há algumas horas. Ao exame: fala frases incompletas, uso de musculatura acessória, sibilos difusos, saturação 93% em ar ambiente. Qual a classificação de gravidade e conduta inicial mais adequada?', 'Crise moderada a grave; broncodilatador de curta ação inalatório repetido, corticoide sistêmico e oxigenoterapia se necessário', 'Crise leve; apenas antitussígeno e retorno se piora', 'Crise leve; apenas observação domiciliar sem medicação', 'Parada respiratória iminente; intubação orotraqueal imediata sem tentativa de tratamento medicamentoso', 'A', 'Sinais como fala entrecortada, uso de musculatura acessória e saturação reduzida indicam crise moderada a grave, tratada com broncodilatador de curta ação inalatório, corticoide sistêmico e oxigenoterapia suplementar se necessário.', 'B: antitussígeno não trata broncoespasmo e não é indicado na asma. C: os sinais de gravidade descritos excluem crise leve e exigem tratamento imediato. D: não há sinais de parada iminente; tratamento medicamentoso deve ser tentado antes de intubação.', 'Em revisão'),
  ('SIM1-073', 'simulado', '1', '73', 'Pediatria', 'Icterícia neonatal - indicação de fototerapia', 'Médio', null, null, 'Recém-nascido a termo, com 4 dias de vida, apresenta icterícia até tronco. Bilirrubina total sérica dentro da faixa de indicação de fototerapia pela curva de Bhutani para a idade pós-natal, sem sinais de hemólise. Qual a conduta mais adequada?', 'Suspender o aleitamento materno definitivamente', 'Indicar exsanguineotransfusão imediatamente', 'Aguardar resolução espontânea, sem qualquer intervenção', 'Iniciar fototerapia e monitorar níveis de bilirrubina', 'D', 'Bilirrubina em nível indicativo de fototerapia pela curva específica para idade pós-natal justifica o início de fototerapia, com monitorização seriada para avaliar resposta e necessidade de escalonamento terapêutico.', 'A: suspensão definitiva do aleitamento não é indicada rotineiramente. B: exsanguineotransfusão é reservada para níveis muito mais elevados ou sinais de encefalopatia aguda. C: aguardar sem tratamento expõe o RN a risco de encefalopatia bilirrubínica se os níveis continuarem subindo.', 'Em revisão'),
  ('SIM1-074', 'simulado', '1', '74', 'Pediatria', 'Desnutrição infantil - classificação', 'Médio', null, null, 'Criança de 18 meses é trazida à UBS para consulta de puericultura. Peso para idade abaixo do percentil 3 na curva de crescimento, sem edema, com apetite preservado. Mãe relata dificuldades socioeconômicas na alimentação. Qual a classificação e conduta mais adequada?', 'Desnutrição grave; internação hospitalar imediata obrigatória', 'Obesidade infantil; orientar restrição calórica', 'Peso adequado para a idade; não é necessária nenhuma conduta', 'Baixo peso para idade; investigação de causas, orientação nutricional e acompanhamento próximo do crescimento', 'D', 'Peso abaixo do percentil 3 caracteriza baixo peso para a idade; a conduta envolve investigar causas, orientar nutrição adequada e acompanhar de perto a curva de crescimento, sem necessariamente exigir internação se não houver sinais de gravidade.', 'A: sem sinais de gravidade (edema, complicações agudas), internação imediata obrigatória não é a primeira conduta. B: o quadro descrito é de baixo peso, não excesso; restrição calórica seria prejudicial. C: o percentil descrito indica déficit de peso, não peso adequado.', 'Em revisão'),
  ('SIM1-075', 'simulado', '1', '75', 'Pediatria', 'Convulsão febril', 'Médio', null, null, 'Criança de 2 anos apresenta episódio de convulsão tônico-clônica generalizada, com duração de 3 minutos, durante quadro febril (temperatura 39°C) por infecção viral de vias aéreas superiores. Recuperação completa da consciência após o episódio, sem sinais neurológicos focais. Qual a conduta mais adequada?', 'Solicitar tomografia de crânio de urgência em todos os casos, independentemente da avaliação clínica', 'Tranquilizar os pais, tratar a causa da febre, orientar sinais de alarme e não é necessário anticonvulsivante de rotina', 'Iniciar anticonvulsivante profilático contínuo imediatamente', 'Investigação com punção lombar obrigatória em todos os casos', 'B', 'Trata-se de convulsão febril simples; a conduta é tranquilizar a família, tratar a causa da febre e orientar sinais de alarme, sem necessidade rotineira de exames de imagem, punção lombar ou anticonvulsivante profilático.', 'A: TC de crânio não é rotina sem sinais neurológicos focais ou outros achados de alarme. C: anticonvulsivante profilático contínuo não é indicado após episódio isolado. D: punção lombar não é obrigatória em toda convulsão febril simples, reservada para suspeita de infecção do SNC.', 'Em revisão'),
  ('SIM1-076', 'simulado', '1', '76', 'Pediatria', 'Bronquiolite viral aguda', 'Médio', null, null, 'Lactente de 4 meses apresenta coriza, tosse e sibilância há 2 dias, primeiro episódio, com desconforto respiratório leve e saturação 95% em ar ambiente, aceitando bem a alimentação. Qual a conduta mais adequada?', 'Iniciar antibioticoterapia empírica de amplo espectro', 'Iniciar corticoide sistêmico e broncodilatador inalatório de rotina', 'Manejo de suporte ambulatorial: desobstrução nasal, manutenção da hidratação/alimentação e orientação de sinais de alarme', 'Internação hospitalar obrigatória para todo primeiro episódio de sibilância', 'C', 'Bronquiolite viral aguda leve, sem sinais de gravidade, é manejada de forma ambulatorial com medidas de suporte: desobstrução nasal, manutenção de hidratação e orientação sobre sinais de piora para retorno.', 'A: bronquiolite tem etiologia viral; antibiótico não está indicado rotineiramente. B: corticoide sistêmico e broncodilatador não têm benefício comprovado de rotina na bronquiolite viral em lactentes. D: internação não é obrigatória na ausência de sinais de gravidade.', 'Em revisão'),
  ('SIM1-077', 'simulado', '1', '77', 'Pediatria', 'Coqueluche', 'Médio', null, null, 'Lactente de 2 meses apresenta tosse paroxística intensa, seguida de guincho inspiratório e episódios de cianose, há 1 semana, sem febre significativa. Qual a hipótese diagnóstica mais provável e conduta?', 'Coqueluche; iniciar macrolídeo (ex: azitromicina) e notificar o caso, com atenção a sinais de gravidade (apneia)', 'Asma; iniciar corticoide inalatório de manutenção', 'Refluxo gastroesofágico; iniciar inibidor de bomba de prótons', 'Bronquiolite viral; apenas suporte, sem necessidade de antibiótico ou notificação', 'A', 'Tosse paroxística com guincho inspiratório e cianose em lactente jovem é característica de coqueluche, doença de notificação compulsória; tratamento com macrolídeo, atenção ao risco de apneia.', 'B: asma não é a hipótese mais provável nesse padrão característico. C: refluxo não explica o padrão paroxístico com guincho e cianose. D: o padrão de tosse paroxística com guincho não é típico de bronquiolite viral simples.', 'Em revisão'),
  ('SIM1-078', 'simulado', '1', '78', 'Pediatria', 'Doença de Kawasaki', 'Difícil', null, null, 'Criança de 3 anos apresenta febre há 6 dias, hiperemia conjuntival bilateral não exsudativa, língua em framboesa, edema de extremidades e exantema polimorfo. Qual a hipótese diagnóstica mais provável e conduta?', 'Escarlatina; iniciar apenas penicilina oral, sem necessidade de avaliação cardiológica', 'Doença de Kawasaki; iniciar imunoglobulina intravenosa e AAS em dose anti-inflamatória, com avaliação cardiológica (risco de aneurisma coronariano)', 'Sarampo; apenas suporte clínico, sem necessidade de tratamento específico', 'Reação alérgica medicamentosa; suspender qualquer medicação e observar', 'B', 'Febre prolongada associada a conjuntivite não exsudativa, língua em framboesa, edema de extremidades e exantema polimorfo preenche critérios para doença de Kawasaki; tratamento com imunoglobulina IV e AAS.', 'A: escarlatina tem outros achados distintos, sem o mesmo risco cardiológico específico. C: sarampo tem apresentação diferente e não gera esse risco coronariano específico. D: o quadro não é sugestivo de reação alérgica isolada.', 'Em revisão'),
  ('SIM1-079', 'simulado', '1', '79', 'Pediatria', 'Refluxo gastroesofágico no lactente', 'Fácil', null, null, 'Lactente de 3 meses, em bom estado geral, ganho de peso adequado, apresenta regurgitações frequentes após as mamadas, sem choro excessivo ou sinais de alarme. Qual a conduta mais adequada?', 'Solicitar endoscopia digestiva alta em todos os casos de regurgitação', 'Iniciar inibidor de bomba de prótons imediatamente, independentemente da gravidade', 'Suspender o aleitamento materno e substituir por fórmula anti-refluxo obrigatoriamente', 'Orientar medidas posturais e fracionamento das mamadas, tranquilizando os pais quanto ao caráter fisiológico do refluxo do lactente', 'D', 'Regurgitações frequentes em lactente com bom estado geral e ganho de peso adequado, sem sinais de alarme, caracterizam refluxo fisiológico; orientação de medidas posturais e tranquilização dos pais.', 'A: endoscopia não é exame de rotina para regurgitação fisiológica. B: IBP não é indicado rotineiramente no refluxo fisiológico sem sinais de doença do refluxo. C: suspensão do aleitamento materno não é indicada rotineiramente.', 'Em revisão'),
  ('SIM1-080', 'simulado', '1', '80', 'Pediatria', 'Constipação intestinal funcional', 'Fácil', null, null, 'Criança de 5 anos apresenta evacuações dolorosas e infrequentes (a cada 4-5 dias), fezes endurecidas, sem sinais de doença orgânica ao exame físico. Qual a conduta mais adequada?', 'Orientação dietética (fibras, hidratação), desimpactação se necessário e uso de laxante conforme protocolo, com acompanhamento', 'Cirurgia para investigação de doença de Hirschsprung em todos os casos, sem outra avaliação', 'Nenhuma conduta é necessária, pois constipação na infância sempre se resolve sozinha', 'Restrição hídrica para reduzir o volume fecal', 'A', 'Constipação intestinal funcional é tratada com orientação dietética, desimpactação fecal quando necessário e laxantes conforme protocolo, com acompanhamento.', 'B: doença de Hirschsprung é diagnóstico diferencial em casos com sinais de alarme, não investigação de rotina. C: constipação funcional sem tratamento pode cronificar. D: restrição hídrica pode piorar a consistência das fezes.', 'Em revisão'),
  ('SIM1-081', 'simulado', '1', '81', 'Pediatria', 'TDAH - avaliação diagnóstica', 'Médio', null, null, 'Criança de 8 anos apresenta dificuldade de concentração, desatenção e agitação motora em múltiplos ambientes (escola e casa) há mais de 6 meses, afetando o desempenho escolar. Qual a conduta mais adequada para avaliação diagnóstica?', 'Avaliação clínica multidisciplinar, com critérios diagnósticos padronizados, considerando os sintomas em múltiplos ambientes e o impacto funcional', 'Iniciar metilfenidato empiricamente antes de qualquer avaliação diagnóstica estruturada', 'Diagnóstico imediato de TDAH apenas com base no relato dos pais, sem outra avaliação', 'Atribuir os sintomas exclusivamente a problemas comportamentais familiares, sem investigação adicional', 'A', 'O diagnóstico de TDAH requer avaliação clínica estruturada, com critérios padronizados, considerando sintomas em múltiplos ambientes e o impacto funcional, muitas vezes multidisciplinar.', 'B: tratamento medicamentoso não deve ser iniciado empiricamente antes de avaliação adequada. C: diagnóstico baseado apenas em relato dos pais, sem critérios estruturados, é insuficiente. D: atribuir exclusivamente a fatores familiares pode atrasar o diagnóstico correto.', 'Em revisão'),
  ('SIM1-082', 'simulado', '1', '82', 'Pediatria', 'Anemia ferropriva na infância', 'Fácil', null, null, 'Criança de 18 meses, em aleitamento materno prolongado sem introdução adequada de alimentos ricos em ferro, apresenta palidez e hemograma com anemia microcítica e hipocrômica. Qual a conduta mais adequada?', 'Nenhuma conduta é necessária, pois anemia nessa idade é sempre fisiológica', 'Transfusão sanguínea de rotina, independentemente da gravidade da anemia', 'Suplementação isolada de vitamina D, sem necessidade de ferro', 'Suplementação de ferro oral e orientação sobre alimentação complementar rica em ferro', 'D', 'Anemia ferropriva na infância, comum quando há atraso na introdução de alimentos ricos em ferro, é tratada com suplementação oral de ferro associada à orientação nutricional adequada.', 'A: anemia com hemoglobina reduzida e sintomas não deve ser considerada apenas fisiológica. B: transfusão não é rotina para anemia ferropriva sem repercussão hemodinâmica grave. C: vitamina D não trata a deficiência de ferro específica descrita.', 'Em revisão'),
  ('SIM1-083', 'simulado', '1', '83', 'Pediatria', 'Púrpura de Henoch-Schönlein', 'Difícil', null, null, 'Criança de 6 anos apresenta púrpura palpável em membros inferiores e nádegas, dor abdominal e artralgia em joelhos e tornozelos, sem trombocitopenia ao hemograma. Qual a hipótese diagnóstica mais provável e conduta?', 'Púrpura de Henoch-Schönlein; tratamento sintomático e monitorização de função renal (risco de nefrite)', 'Meningococcemia; iniciar antibioticoterapia de amplo espectro imediatamente, independente do estado geral', 'Alergia alimentar; apenas suspender possíveis alérgenos, sem outra investigação', 'Púrpura trombocitopênica idiopática; iniciar corticoide em altas doses imediatamente', 'A', 'Púrpura palpável em membros inferiores/nádegas associada a dor abdominal e artralgia, com plaquetas normais, é característica de púrpura de Henoch-Schönlein; conduta sintomática com monitorização renal.', 'B: meningococcemia geralmente cursa com toxemia importante e evolução rápida, diferente do quadro. C: o padrão descrito não é explicado apenas por alergia alimentar. D: PTI cursa com trombocitopenia, ausente neste caso.', 'Em revisão'),
  ('SIM1-084', 'simulado', '1', '84', 'Pediatria', 'Escabiose - manejo', 'Fácil', null, null, 'Criança apresenta prurido intenso, principalmente noturno, com lesões papulares e sulcos em espaços interdigitais, punhos e região genital. Outros membros da família relatam sintomas semelhantes. Qual a conduta mais adequada?', 'Tratamento apenas do paciente índice, sem necessidade de tratar os contactantes', 'Apenas anti-histamínico oral, sem necessidade de tratamento tópico específico', 'Corticoide tópico isolado, sem necessidade de tratamento específico para o ácaro', 'Tratamento com escabicida tópico (ex: permetrina) para o paciente e contactantes domiciliares, com lavagem de roupas de cama', 'D', 'Escabiose é tratada com escabicida tópico, aplicado no paciente e em todos os contactantes domiciliares simultaneamente, associado a medidas de higiene das roupas.', 'A: não tratar os contactantes permite reinfestação. B: anti-histamínico pode aliviar o prurido, mas não trata a infestação. C: corticoide tópico isolado não elimina o ácaro, podendo mascarar o quadro.', 'Em revisão'),
  ('SIM1-085', 'simulado', '1', '85', 'Pediatria', 'Otite média aguda', 'Médio', null, null, 'Criança de 2 anos apresenta febre, irritabilidade e dor em ouvido direito há 2 dias. Otoscopia mostra membrana timpânica hiperemiada e abaulada. Qual a conduta mais adequada?', 'Apenas analgesia, sem necessidade de antibiótico em nenhum caso de otite média aguda', 'Miringotomia de urgência em todos os casos, independentemente da gravidade', 'Observação sem qualquer tratamento, pois otite média sempre resolve espontaneamente', 'Antibioticoterapia (ex: amoxicilina) e analgesia, considerando gravidade e idade da criança', 'D', 'Otite média aguda em criança pequena (<2 anos) com sinais de gravidade geralmente tem indicação de antibioticoterapia associada a analgesia adequada.', 'A: em menores de 2 anos com sinais de gravidade, o antibiótico costuma ser indicado. B: miringotomia é reservada para casos específicos, não é conduta de rotina. C: otite com sinais de gravidade não deve ser deixada sem tratamento.', 'Em revisão'),
  ('SIM1-086', 'simulado', '1', '86', 'Pediatria', 'Faringoamigdalite estreptocócica', 'Fácil', null, null, 'Criança de 7 anos apresenta febre, dor de garganta intensa, exsudato amigdaliano purulento e linfadenopatia cervical dolorosa, sem tosse ou coriza associada. Qual a conduta mais adequada?', 'Iniciar apenas anti-histamínico, pois o quadro é provavelmente alérgico', 'Considerar tratamento com penicilina (ou amoxicilina) para faringoamigdalite estreptocócica, conforme critérios clínicos/teste rápido quando disponível', 'Não tratar com antibiótico em nenhuma circunstância, pois faringite é sempre viral', 'Indicar amigdalectomia de urgência como tratamento do episódio agudo', 'B', 'Febre, exsudato purulento, linfadenopatia cervical dolorosa e ausência de sintomas de via aérea superior sugerem etiologia estreptocócica; tratamento com penicilina ou amoxicilina.', 'A: o quadro não é sugestivo de processo alérgico. C: o quadro apresentado tem características clássicas de etiologia estreptocócica, que se beneficia de antibiótico. D: amigdalectomia não é tratamento do episódio agudo.', 'Em revisão'),
  ('SIM1-087', 'simulado', '1', '87', 'Pediatria', 'Aleitamento materno exclusivo - recomendações', 'Fácil', null, null, 'Mãe de recém-nascido saudável, sem contraindicações, pergunta na UBS até quando deve manter o aleitamento materno exclusivo antes de iniciar a alimentação complementar. Qual a orientação mais adequada segundo o Ministério da Saúde?', 'Aleitamento materno exclusivo por tempo indeterminado, sem necessidade de alimentação complementar', 'Aleitamento materno exclusivo até os 6 meses de vida, com introdução de alimentação complementar a partir de então, mantendo o aleitamento até os 2 anos ou mais', 'Introdução de água e chás já a partir do primeiro mês de vida, associada ao leite materno', 'Aleitamento materno exclusivo até os 3 meses, com introdução obrigatória de fórmula a partir de então', 'B', 'A recomendação do Ministério da Saúde é aleitamento materno exclusivo até os 6 meses, com introdução da alimentação complementar a partir dessa idade, mantendo o aleitamento até os 2 anos ou mais.', 'A: alimentação complementar é necessária a partir dos 6 meses. C: água e chás não devem ser introduzidos antes dos 6 meses em aleitamento exclusivo. D: introdução de fórmula aos 3 meses não é a recomendação padrão.', 'Em revisão'),
  ('SIM1-088', 'simulado', '1', '88', 'Medicina Preventiva e Social', 'Vigilância epidemiológica / notificação compulsória', 'Fácil', null, null, 'Médico de UBS atende paciente com diagnóstico clínico de dengue com sinais de alarme (dor abdominal intensa, vômitos persistentes). Além da conduta clínica, qual providência de saúde pública é obrigatória?', 'Notificação apenas pelo serviço de vigilância hospitalar, não cabendo à UBS', 'Notificação facultativa, a critério do médico assistente', 'Notificação apenas se houver óbito confirmado', 'Notificação compulsória imediata às autoridades de vigilância epidemiológica', 'D', 'Dengue com sinais de alarme é doença de notificação compulsória imediata (até 24h) no Brasil, dado seu potencial de gravidade e a importância para vigilância epidemiológica e controle de surtos.', 'A: a notificação é responsabilidade de qualquer serviço que atenda o caso, incluindo a UBS. B: notificação compulsória não é facultativa, é obrigação legal do profissional de saúde. C: a notificação não depende de óbito; casos suspeitos/confirmados já exigem notificação.', 'Em revisão'),
  ('SIM1-089', 'simulado', '1', '89', 'Medicina Preventiva e Social', 'Atributos da Atenção Primária à Saúde', 'Médio', null, null, 'Uma Unidade Básica de Saúde organiza seu atendimento de forma que o mesmo paciente é sempre acompanhado pela mesma equipe de referência ao longo do tempo, integrando cuidados de diferentes especialidades quando necessário. Esse conjunto de características corresponde a quais atributos da Atenção Primária à Saúde?', 'Descentralização administrativa', 'Longitudinalidade e coordenação do cuidado', 'Universalidade e integralidade, exclusivamente', 'Regionalização e hierarquização', 'B', 'Longitudinalidade refere-se ao vínculo contínuo entre paciente e equipe ao longo do tempo; coordenação do cuidado refere-se à integração de diferentes pontos de atenção em torno das necessidades do paciente — ambos atributos essenciais da APS.', 'A: descentralização é um princípio organizativo do SUS, não um atributo da APS descrito no caso. C: universalidade/integralidade são princípios do SUS, mas não descrevem especificamente o cenário do caso. D: regionalização/hierarquização dizem respeito à organização da rede, não ao vínculo longitudinal descrito.', 'Em revisão'),
  ('SIM1-090', 'simulado', '1', '90', 'Medicina Preventiva e Social', 'Indicadores de saúde / mortalidade infantil', 'Médio', null, null, 'Em um município, ocorreram 30 óbitos de crianças menores de 1 ano em determinado ano, sobre um total de 3.000 nascidos vivos no mesmo período e local. Qual é o coeficiente de mortalidade infantil desse município, e o que ele reflete?', '10 por mil nascidos vivos; reflete principalmente condições socioeconômicas e acesso a serviços de saúde', '30 por mil nascidos vivos; reflete apenas mortalidade neonatal precoce', '1 por mil nascidos vivos; reflete exclusivamente causas obstétricas', '100 por mil nascidos vivos; indicador exclusivo de mortalidade por causas infecciosas', 'A', 'Coeficiente de mortalidade infantil = (óbitos <1 ano / nascidos vivos) x 1000 = (30/3000)x1000 = 10 por mil nascidos vivos. É um indicador sensível às condições de vida, saneamento, acesso a saúde e qualidade da assistência pré-natal/neonatal.', 'B: erro de cálculo (30 é o número absoluto de óbitos, não o coeficiente) e restringe indevidamente à mortalidade neonatal precoce. C: cálculo incorreto e definição incompleta (o indicador não se limita a causas obstétricas). D: cálculo e afirmação incorretos; o indicador engloba múltiplas causas, não só infecciosas.', 'Em revisão'),
  ('SIM1-091', 'simulado', '1', '91', 'Medicina Preventiva e Social', 'Rastreamento de câncer de colo uterino', 'Médio', null, null, 'Mulher de 30 anos, sem comorbidades, com vida sexual ativa, procura a UBS para rotina ginecológica. Nunca realizou exame preventivo. Segundo as diretrizes do Ministério da Saúde, qual a conduta de rastreamento mais adequada?', 'Não é necessário rastreamento antes dos 40 anos', 'Realizar citologia oncótica (Papanicolau) anualmente, indefinidamente', 'Realizar apenas exame de HPV isolado, sem necessidade de citologia', 'Realizar citologia oncótica; se dois exames anuais consecutivos normais, repetir a cada 3 anos', 'D', 'O rastreamento do câncer de colo do útero no Brasil é feito por citologia oncótica, iniciando aos 25 anos em mulheres com vida sexual ativa até os 64 anos, com periodicidade anual inicialmente; após dois exames anuais consecutivos normais, o intervalo passa a ser trienal.', 'A: o rastreamento se inicia aos 25 anos em mulheres com vida sexual ativa, não aos 40. B: rastreamento anual indefinido não é a recomendação após dois exames normais consecutivos. C: o protocolo nacional ainda é baseado na citologia oncótica na maior parte da rede.', 'Em revisão'),
  ('SIM1-092', 'simulado', '1', '92', 'Medicina Preventiva e Social', 'Transição demográfica / pirâmide etária', 'Médio', null, null, 'Um município apresenta pirâmide etária com base estreita e topo alargado, refletindo redução da natalidade e aumento da expectativa de vida ao longo das décadas. Esse padrão demográfico está associado a qual mudança esperada nas necessidades de saúde da população?', 'Nenhuma mudança relevante na organização dos serviços de saúde', 'Redução da demanda por doenças crônico-degenerativas e aumento da demanda por saúde materno-infantil', 'Aumento da demanda por cuidados relacionados a doenças crônico-degenerativas e menor pressão sobre serviços materno-infantis', 'Aumento exclusivo da mortalidade infantil como principal desafio de saúde pública', 'C', 'Uma pirâmide com base estreita e topo alargado reflete uma população envelhecendo — a transição demográfica —, associada a maior demanda por cuidados de doenças crônico-degenerativas e menor pressão proporcional sobre serviços materno-infantis.', 'A: a mudança no perfil demográfico exige reorganização dos serviços de saúde. B: o padrão descrito é o oposto: menos demanda materno-infantil e mais demanda por doenças crônicas. D: o padrão descrito reflete população envelhecida, não indica aumento de mortalidade infantil.', 'Em revisão'),
  ('SIM1-093', 'simulado', '1', '93', 'Medicina Preventiva e Social', 'Redes de Atenção à Saúde - referência e contrarreferência', 'Médio', null, null, 'Uma UBS encaminha um paciente com suspeita de neoplasia para avaliação especializada em um hospital de referência regional. Após a consulta, o especialista devolve um relatório detalhado com orientações de seguimento para a equipe da atenção primária continuar o cuidado. Esse fluxo de comunicação entre os níveis de atenção caracteriza qual princípio organizativo do SUS?', 'Hierarquização, apenas', 'Sistema de referência e contrarreferência, dentro da Rede de Atenção à Saúde (RAS)', 'Municipalização exclusiva dos serviços de saúde', 'Universalidade de acesso', 'B', 'O fluxo descrito — encaminhamento da atenção primária para um nível especializado e o retorno de informações para a continuidade do cuidado — caracteriza o sistema de referência e contrarreferência, essencial para a coordenação do cuidado dentro da Rede de Atenção à Saúde.', 'A: hierarquização descreve a organização por níveis de complexidade, mas não capta o fluxo de ida e volta descrito. C: o caso não trata de municipalização, mas de articulação entre níveis assistenciais. D: universalidade refere-se ao acesso garantido a todos, não ao fluxo de comunicação.', 'Em revisão'),
  ('SIM1-094', 'simulado', '1', '94', 'Medicina Preventiva e Social', 'Indicadores epidemiológicos - incidência e prevalência', 'Fácil', null, null, 'Em uma cidade com população estável de 100.000 habitantes, foram registrados 500 novos casos de uma doença ao longo de um ano, e o total de casos existentes (novos e antigos) no fim do ano foi de 2.000. Qual conceito epidemiológico corresponde a cada um desses números, respectivamente?', 'Prevalência (500 novos casos) e incidência (2.000 casos totais)', 'Incidência (500 novos casos) e prevalência (2.000 casos totais)', 'Ambos os números representam apenas incidência, em períodos diferentes', 'Ambos os números representam apenas prevalência, em momentos diferentes', 'B', 'Incidência refere-se ao número de casos novos em um período (500 no ano); prevalência refere-se ao total de casos existentes em um determinado momento (2.000 ao fim do ano).', 'A: inverte os conceitos corretos. C: o segundo número caracteriza prevalência, não incidência. D: os dois números representam conceitos diferentes, não apenas prevalência.', 'Em revisão'),
  ('SIM1-095', 'simulado', '1', '95', 'Medicina Preventiva e Social', 'Sensibilidade e especificidade de testes diagnósticos', 'Médio', null, null, 'Um novo teste diagnóstico para determinada doença apresenta alta sensibilidade e baixa especificidade. Qual a implicação mais adequada do uso desse teste na prática clínica?', 'O teste é adequado apenas para confirmar diagnóstico em pacientes já sintomáticos, não para rastreamento', 'O teste é ideal tanto para rastreamento quanto para confirmação diagnóstica definitiva, sem necessidade de outros exames', 'O teste é útil para rastreamento inicial (poucos falsos negativos), mas resultados positivos exigem confirmação com teste mais específico, pelo risco de falsos positivos', 'O teste deve ser evitado, pois alta sensibilidade sempre indica baixa qualidade do exame', 'C', 'Um teste com alta sensibilidade tem poucos falsos negativos, sendo útil para rastreamento; a baixa especificidade gera mais falsos positivos, exigindo confirmação com um teste mais específico.', 'A: testes de alta sensibilidade são particularmente úteis para rastreamento. B: baixa especificidade compromete o uso do teste como confirmatório isolado. D: alta sensibilidade não indica baixa qualidade; depende do objetivo do teste.', 'Em revisão'),
  ('SIM1-096', 'simulado', '1', '96', 'Medicina Preventiva e Social', 'Determinantes sociais da saúde', 'Médio', null, null, 'Um estudo demonstra que famílias de baixa renda, com menor escolaridade e moradia precária, apresentam maior incidência de doenças infecciosas e maior mortalidade infantil em comparação a famílias de maior renda na mesma cidade. Esse achado ilustra principalmente qual conceito em saúde coletiva?', 'Fenômeno restrito a países de baixa renda, sem relevância para o contexto brasileiro', 'Acaso estatístico, sem relação causal entre condição socioeconômica e saúde', 'Determinantes exclusivamente biológicos das doenças infecciosas, sem relação com fatores sociais', 'Determinantes sociais da saúde, que influenciam diretamente as condições de saúde e adoecimento das populações', 'D', 'A associação entre condições socioeconômicas e piores desfechos de saúde ilustra o conceito de determinantes sociais da saúde, que reconhece que fatores sociais, econômicos e ambientais influenciam o processo saúde-doença.', 'A: determinantes sociais são relevantes em todos os contextos, incluindo o Brasil. B: a associação é amplamente documentada, não sendo mero acaso. C: fatores biológicos isolados não explicam as diferenças entre grupos socioeconômicos distintos na mesma cidade.', 'Em revisão'),
  ('SIM1-097', 'simulado', '1', '97', 'Medicina Preventiva e Social', 'Vigilância sanitária', 'Fácil', null, null, 'Um restaurante é fiscalizado por apresentar condições inadequadas de armazenamento de alimentos, resultando em interdição parcial do estabelecimento até a regularização. Essa ação é de responsabilidade de qual área da vigilância em saúde?', 'Vigilância sanitária, responsável por normatizar e fiscalizar produtos, serviços e ambientes que possam representar risco à saúde da população', 'Vigilância epidemiológica, responsável exclusivamente pelo monitoramento de doenças transmissíveis', 'Vigilância ambiental, responsável apenas pelo monitoramento da qualidade da água e do ar', 'Atenção primária à saúde, responsável pela fiscalização de estabelecimentos comerciais', 'A', 'A vigilância sanitária é responsável por ações de fiscalização e regulação de produtos, serviços e ambientes, visando eliminar, diminuir ou prevenir riscos à saúde da população.', 'B: a vigilância epidemiológica atua no monitoramento e controle de doenças e agravos, não na fiscalização de estabelecimentos. C: a vigilância ambiental tem outro escopo. D: a atenção primária não tem como atribuição a fiscalização sanitária.', 'Em revisão'),
  ('SIM1-098', 'simulado', '1', '98', 'Medicina Preventiva e Social', 'Imunização - contraindicações vacinais', 'Médio', null, null, 'Criança de 6 meses, em tratamento com corticoide sistêmico em dose imunossupressora para doença de base, deve receber vacina de rotina do calendário nacional. Qual orientação é mais adequada em relação às vacinas de vírus vivo atenuado?', 'O uso de corticoide não tem nenhuma relação com a segurança de vacinas de vírus vivo', 'Todas as vacinas do calendário devem ser aplicadas normalmente, independentemente do uso de imunossupressores', 'Vacinas de vírus vivo atenuado devem ser adiadas enquanto a criança estiver em uso de corticoide em dose imunossupressora, sendo administradas após suspensão adequada da medicação', 'Vacinas inativadas também devem ser suspensas nesse contexto', 'C', 'Crianças em uso de corticoide sistêmico em dose imunossupressora têm contraindicação temporária para vacinas de vírus vivo atenuado, pelo risco de doença vacinal disseminada.', 'A: há relação direta e relevante entre imunossupressão e segurança de vacinas de vírus vivo. B: vacinas de vírus vivo têm contraindicação específica nesse contexto. D: vacinas inativadas geralmente podem ser mantidas mesmo em imunossupressão.', 'Em revisão'),
  ('SIM1-099', 'simulado', '1', '99', 'Medicina Preventiva e Social', 'Saúde do trabalhador - notificação de agravos', 'Médio', null, null, 'Um trabalhador de fábrica desenvolve perda auditiva progressiva relacionada à exposição ocupacional a ruído intenso sem uso adequado de proteção auricular. Além da conduta clínica individual, qual providência de saúde pública é esperada?', 'Notificação apenas se houver afastamento do trabalho superior a 15 dias', 'Notificação do agravo relacionado ao trabalho e investigação das condições de segurança no ambiente laboral', 'Nenhuma notificação é necessária, pois perda auditiva não é considerada doença ocupacional', 'A responsabilidade é exclusivamente da empresa, sem necessidade de notificação pelos serviços de saúde', 'B', 'Perda auditiva induzida por ruído ocupacional é agravo relacionado ao trabalho de notificação compulsória; deve-se notificar e investigar as condições de segurança do ambiente laboral.', 'A: a notificação não depende do tempo de afastamento. C: perda auditiva induzida por ruído é reconhecida como doença ocupacional e deve ser notificada. D: a notificação pelos serviços de saúde é complementar à responsabilidade da empresa.', 'Em revisão'),
  ('SIM1-100', 'simulado', '1', '100', 'Medicina Preventiva e Social', 'Política Nacional de Atenção Básica - territorialização', 'Médio', null, null, 'Uma equipe de Estratégia Saúde da Família atua com território adscrito definido, realizando cadastramento das famílias, visitas domiciliares regulares e acompanhamento longitudinal da população residente na área. Esses elementos são característicos de qual princípio organizativo previsto na Política Nacional de Atenção Básica?', 'Regionalização da alta complexidade hospitalar', 'Hierarquização exclusiva dos níveis de atenção, sem relação com território', 'Livre demanda, sem necessidade de território definido', 'Territorialização e adscrição de clientela, associadas ao vínculo longitudinal entre equipe e população', 'D', 'A definição de território adscrito, o cadastramento das famílias e o acompanhamento longitudinal caracterizam os princípios de territorialização e adscrição de clientela da PNAB.', 'A: regionalização da alta complexidade não é o conceito ilustrado. B: hierarquização refere-se à organização por níveis de complexidade, não ao território e vínculo descritos. C: livre demanda sem território definido é o oposto do modelo descrito.', 'Em revisão')
